SEMANTIC_MOCK_PROC_NAMES = {_mock_proc_name(name) for name in SEMANTIC_MOCK_COMMANDS}
RUNTIME_STATUS_VALUES = frozenset(
    {"handwritten-mock", "semantic-mock", "generated-stub", "no-runtime-handler"}
)
TARGET_STATUS_VALUES = frozenset(
    {
        "available-in-tmos-17.5",
        "introduced-after-tmos-17.5",
        "unavailable-in-tmos-17.5",
    }
)


def _capability_status(proc_name: str, handwritten: set[str], generated: set[str]) -> str:
    if proc_name in SEMANTIC_MOCK_PROC_NAMES:
        return "semantic-mock"
    if proc_name in handwritten:
        return "handwritten-mock"
    if proc_name in generated:
        return "generated-stub"
    return "no-runtime-handler"


def _catalog_kind(name: str, spec: Any) -> str:
    """Classify a registry entry as F5 iRule or Tcl support surface."""
    if name == "when":
        return "irule-language"
    namespace = name.split("::", 1)[0] if "::" in name else ""
    hover = getattr(spec, "hover", None)
    source = getattr(hover, "source", "") if hover else ""
    if not isinstance(source, str):
        source = ""
    if (
        namespace.isupper()
        or bool(getattr(spec, "event_requires", None))
        or source.startswith("https://clouddocs.f5.com/api/irules/")
    ):
        return "f5-irule"
    if (
        getattr(spec, "tcllib_package", None)
        or getattr(spec, "required_package", None)
    ):
        return "tcllib"
    return "tcl-core"


def _catalog_event_names(namespace_registry: Any) -> list[str]:
    """Return the pinned event catalog plus documented 17.5 compatibility overrides."""
    return sorted(set(namespace_registry.all_event_names()) | set(TMOS_17_5_EVENT_OVERRIDES))


def _f5_catalog_command_names(command_registry: Any) -> list[str]:
    """Return only F5 commands, excluding Tk specs loaded by the Tcl bridge.

    The tcl-lsp test bridge may load Tk after an emulator session starts. Tk
    specs use ``dialects=None`` and therefore appear in a later
    ``command_names(dialect="f5-irules")`` query even though they are not part
    of the F5 iRules catalog. Filter them by their explicit package marker so
    catalog and conformance counts stay stable across process lifetime.
    """
    names: list[str] = []
    for name in command_registry.command_names(dialect="f5-irules"):
        specs = getattr(command_registry, "specs_by_name", {}).get(name, ())
        if any(
            getattr(spec, "required_package", None) != "Tk"
            and (
                getattr(spec, "dialects", None) is None
                or "f5-irules" in getattr(spec, "dialects", ())
            )
            for spec in specs
        ):
            names.append(name)
    return sorted(names)


def _f5_catalog_spec(command_registry: Any, name: str) -> Any | None:
    """Select the F5 spec when Tcl/Tk share a command name such as ``event``."""
    specs = getattr(command_registry, "specs_by_name", {}).get(name, ())
    for spec in reversed(specs):
        if getattr(spec, "required_package", None) == "Tk":
            continue
        dialects = getattr(spec, "dialects", None)
        if dialects is None or "f5-irules" in dialects:
            return spec
    return None


def _build_capabilities(
    root: Path,
    offset: int,
    limit: int,
    *,
    namespace: str | None = None,
    runtime_status: str | None = None,
    target_status: str | None = None,
) -> dict[str, Any]:
    """Build a chunked, machine-readable view of the tcl-lsp F5 registry."""
    if offset < 0:
        raise EmulatorInputError("capability offset must be non-negative")
    if not 1 <= limit <= 1000:
        raise EmulatorInputError("capability limit must be between 1 and 1000")
    for field, value, allowed in (
        ("namespace", namespace, None),
        ("runtime_status", runtime_status, RUNTIME_STATUS_VALUES),
        ("target_status", target_status, TARGET_STATUS_VALUES),
    ):
        if value is not None and (not isinstance(value, str) or not value):
            raise EmulatorInputError(f"capability {field} must be a non-empty string")
        if value is not None and allowed is not None and value not in allowed:
            raise EmulatorInputError(
                f"capability {field} must be one of: {', '.join(sorted(allowed))}"
            )

    _load_session_class(root)
    try:
        from compiler.registry import REGISTRY
        from compiler.registry.namespace_data import PROFILE_SPECS
        from compiler.registry.namespace_registry import NAMESPACE_REGISTRY
    except ImportError as exc:  # pragma: no cover - depends on external checkout
        raise EmulatorInputError(f"could not load tcl-lsp capability registry: {exc}") from exc

    command_names = _f5_catalog_command_names(REGISTRY)
    tcl_dir = root / "tooling" / "irule_test" / "tcl"
    handwritten = _proc_names(tcl_dir / "command_mocks.tcl")
    generated = _proc_names(tcl_dir / "_mock_stubs.tcl")

    commands: list[dict[str, Any]] = []
    status_counts = {
        "handwritten-mock": 0,
        "semantic-mock": 0,
        "generated-stub": 0,
        "no-runtime-handler": 0,
    }
    target_status_counts = {
        "available-in-tmos-17.5": 0,
        "introduced-after-tmos-17.5": 0,
        "unavailable-in-tmos-17.5": 0,
    }
    for name in command_names:
        spec = _f5_catalog_spec(REGISTRY, name)
        if spec is None:  # pragma: no cover - registry contract guard
            continue
        proc_name = _mock_proc_name(name)
        command_runtime_status = _capability_status(proc_name, handwritten, generated)
        status_counts[command_runtime_status] += 1
        command_target_status = _target_status(
            name,
            TMOS_17_5_POST_TARGET_COMMANDS,
            TMOS_17_5_UNAVAILABLE_COMMANDS,
        )
        target_status_counts[command_target_status] += 1
        requirement = spec.event_requires
        hover = getattr(spec, "hover", None)
        commands.append(
            {
                "name": name,
                "namespace": name.split("::", 1)[0] if "::" in name else "",
                "catalog_kind": _catalog_kind(name, spec),
                "subcommands": sorted(spec.subcommands),
                "documentation": {
                    "summary": getattr(hover, "summary", "") if hover else "",
                    "synopsis": list(getattr(hover, "synopsis", ()) or ()) if hover else [],
                    "return_value": getattr(hover, "return_value", "") if hover else "",
                    "source": getattr(hover, "source", "") if hover else "",
                },
                "pure": bool(spec.pure),
                "unsafe": bool(spec.unsafe),
                "runtime_status": command_runtime_status,
                "target_status": command_target_status,
                "event_requirements": {
                    "profiles": sorted(requirement.profiles) if requirement else [],
                    "also_in": sorted(requirement.also_in) if requirement else [],
                    "transport": requirement.transport if requirement else None,
                    "capability": requirement.capability if requirement else None,
                    "client_side": bool(requirement.client_side) if requirement else False,
                    "server_side": bool(requirement.server_side) if requirement else False,
                    "flow": bool(requirement.flow) if requirement else False,
                    "init_only": bool(requirement.init_only) if requirement else False,
                },
            }
        )

    events: list[dict[str, Any]] = []
    for name in _catalog_event_names(NAMESPACE_REGISTRY):
        props = NAMESPACE_REGISTRY.get_props(name)
        override = TMOS_17_5_EVENT_OVERRIDES.get(name)
        if props is None and override is None:  # pragma: no cover - registry contract guard
            continue
        event_data = override if props is None else {
            "multiplicity": NAMESPACE_REGISTRY.event_multiplicity(name),
            "client_side": bool(props.client_side),
            "server_side": bool(props.server_side),
            "transport": props.transport,
            "implied_profiles": props.implied_profiles,
            "flow": bool(props.flow),
            "deprecated": bool(props.deprecated),
            "common": bool(props.common),
        }
        transport = event_data["transport"]
        events.append(
            {
                "name": name,
                "target_status": _target_status(
                    name,
                    TMOS_17_5_POST_TARGET_EVENTS,
                    TMOS_17_5_UNAVAILABLE_EVENTS,
                ),
                "multiplicity": event_data["multiplicity"],
                "client_side": event_data["client_side"],
                "server_side": event_data["server_side"],
                "transport": list(transport) if isinstance(transport, tuple) else transport,
                "implied_profiles": sorted(event_data["implied_profiles"]),
                "flow": event_data["flow"],
                "deprecated": event_data["deprecated"],
                "common": event_data["common"],
            }
        )

    profiles = [
        {
            "name": name,
            "layer": spec.layer,
            "side": spec.side,
            "requires": sorted(spec.requires),
            "conflicts": sorted(spec.conflicts),
            "capabilities": sorted(spec.capabilities),
        }
        for name, spec in sorted(PROFILE_SPECS.items())
    ]

    filtered_commands = [
        command
        for command in commands
        if (
            namespace is None
            or command["namespace"] == namespace
        )
        and (runtime_status is None or command["runtime_status"] == runtime_status)
        and (target_status is None or command["target_status"] == target_status)
    ]
    start = min(offset, len(filtered_commands))
    end = min(start + limit, len(filtered_commands))
    return {
        "status": "ok",
        "schema_version": 1,
        "profile": "tmos-17.5",
        "tmos_version": TMOS_VERSION,
        "source": {
            "name": "tcl-lsp f5-irules registry",
            "commit": os.environ.get("TCL_LSP_COMMIT", "unknown"),
            "event_overrides": sorted(TMOS_17_5_EVENT_OVERRIDES),
        },
        "summary": {
            "command_count": len(commands),
            "filtered_command_count": len(filtered_commands),
            "event_count": len(events),
            "profile_count": len(profiles),
            "runtime_status_counts": status_counts,
            "target_status_counts": target_status_counts,
        },
        "chunk": {
            "offset": offset,
            "limit": limit,
            "count": end - start,
            "total": len(filtered_commands),
            "has_more": end < len(filtered_commands),
        },
        "filter": {
            "namespace": namespace,
            "runtime_status": runtime_status,
            "target_status": target_status,
        },
        "commands": filtered_commands[start:end],
        "events": events,
        "profiles": profiles,
    }


def _build_catalog(
    root: Path,
    chunk_size: int,
    *,
    namespace: str | None = None,
    runtime_status: str | None = None,
    target_status: str | None = None,
) -> dict[str, Any]:
    """Materialize the complete filtered command catalog as deterministic chunks."""
    if not 1 <= chunk_size <= 1000:
        raise EmulatorInputError("catalog chunk size must be between 1 and 1000")
    filters = {
        "namespace": namespace,
        "runtime_status": runtime_status,
        "target_status": target_status,
    }
    first = _build_capabilities(root, 0, chunk_size, **filters)
    chunks: list[dict[str, Any]] = []
    page = first
    while True:
        chunk = page["chunk"]
        chunks.append(
            {
                "offset": chunk["offset"],
                "limit": chunk["limit"],
                "count": chunk["count"],
                "has_more": chunk["has_more"],
                "commands": page["commands"],
            }
        )
        if not chunk["has_more"]:
            break
        if chunk["count"] <= 0:
            raise EmulatorInputError("catalog chunk pagination made no progress")
        page = _build_capabilities(
            root,
            chunk["offset"] + chunk["count"],
            chunk_size,
            **filters,
        )
    return {
        "status": "ok",
        "schema_version": 1,
        "profile": "tmos-17.5",
        "tmos_version": TMOS_VERSION,
        "source": first["source"],
        "filter": first["filter"],
        "summary": first["summary"],
        "chunking": {
            "chunk_size": chunk_size,
            "chunk_count": len(chunks),
        },
        "chunks": chunks,
        "events": first["events"],
        "profiles": first["profiles"],
    }


def _build_capture_campaign(
    root: Path,
    offset: int,
    limit: int,
    *,
    namespace: str | None = None,
    runtime_status: str | None = None,
    target_status: str | None = "available-in-tmos-17.5",
) -> dict[str, Any]:
    """Build chunked external-reference work units from the 17.5 catalog."""
    if offset < 0:
        raise EmulatorInputError("capture campaign offset must be non-negative")
    if not 1 <= limit <= 1000:
        raise EmulatorInputError("capture campaign limit must be between 1 and 1000")
    catalog = _build_catalog(
        root,
        1000,
        namespace=namespace,
        runtime_status=runtime_status,
        target_status=target_status,
    )
    candidate_commands = [
        command
        for chunk in catalog["chunks"]
        for command in chunk["commands"]
        if command["catalog_kind"] == "f5-irule"
    ]
    runtime_status_counts = {status: 0 for status in sorted(RUNTIME_STATUS_VALUES)}
    target_status_counts = {status: 0 for status in sorted(TARGET_STATUS_VALUES)}
    for command in candidate_commands:
        runtime_status_counts[command["runtime_status"]] += 1
        target_status_counts[command["target_status"]] += 1

    start = min(offset, len(candidate_commands))
    end = min(start + limit, len(candidate_commands))
    cases: list[dict[str, Any]] = []
    for command in candidate_commands[start:end]:
        kind = command["catalog_kind"]
        runnable_target = command["target_status"] == "available-in-tmos-17.5"
        if kind == "f5-irule" and runnable_target:
            collector_action = (
                "execute this command on TMOS 17.5 with a valid event, profile, "
                "argument, and fixture state; emit the observed JSON result"
            )
            operation = "command_probe"
        else:
            collector_action = (
                "record a syntax/catalog observation; this entry is not a "
                "runnable TMOS 17.5 command probe"
            )
            operation = "catalog_observation"
        cases.append(
            {
                "id": f"{operation}:{command['name']}",
                "operation": operation,
                "name": command["name"],
                "namespace": command["namespace"],
                "catalog_kind": kind,
                "target_status": command["target_status"],
                "runtime_status": command["runtime_status"],
                "pure": command["pure"],
                "unsafe": command["unsafe"],
                "subcommands": command["subcommands"],
                "event_requirements": command["event_requirements"],
                "documentation": command["documentation"],
                "collector_action": collector_action,
            }
        )
    return {
        "status": "ok",
        "schema_version": 1,
        "profile": "tmos-17.5",
        "tmos_version": TMOS_VERSION,
        "campaign": {
            "name": "tmos-17.5-command-reference",
            "schema_version": 1,
            "source": catalog["source"],
            "catalog_kind": "f5-irule",
            "filter": catalog["filter"],
            "summary": {
                "candidate_count": len(candidate_commands),
                "catalog_command_count": catalog["summary"]["command_count"],
                "catalog_filtered_command_count": catalog["summary"]["filtered_command_count"],
                "runtime_status_counts": runtime_status_counts,
                "target_status_counts": target_status_counts,
            },
            "chunk": {
                "offset": offset,
                "limit": limit,
                "count": end - start,
                "total": len(candidate_commands),
                "has_more": end < len(candidate_commands),
            },
            "cases": cases,
        },
    }


def _probe_event_inventory(root: Path) -> list[tuple[str, Any]]:
    """Load the target-valid event properties used by collector templates."""
    _load_session_class(root)
    try:
        from compiler.registry.namespace_data import get_event_props
        from compiler.registry.namespace_models import EventProps
        from compiler.registry.namespace_registry import NAMESPACE_REGISTRY
    except ImportError as exc:  # pragma: no cover - depends on external checkout
        raise EmulatorInputError(
            f"could not load tcl-lsp event registry: {exc}"
        ) from exc

    inventory: list[tuple[str, Any]] = []
    for name in _catalog_event_names(NAMESPACE_REGISTRY):
        if name in TMOS_17_5_POST_TARGET_EVENTS or name in TMOS_17_5_UNAVAILABLE_EVENTS:
            continue
        props = get_event_props(name)
        if props is None and name in TMOS_17_5_EVENT_OVERRIDES:
            override = TMOS_17_5_EVENT_OVERRIDES[name]
            props = EventProps(
                client_side=override["client_side"],
                server_side=override["server_side"],
                transport=override["transport"],
                implied_profiles=override["implied_profiles"],
                flow=override["flow"],
                deprecated=override["deprecated"],
                common=override["common"],
            )
        if props is not None:
            inventory.append((name, props))
    return inventory


def _command_probe_template(
    root: Path,
    command: str,
    event_inventory: list[tuple[str, Any]],
) -> dict[str, Any]:
    """Choose a valid event/profile shell without guessing command arguments."""
    _load_session_class(root)
    try:
        from compiler.registry import REGISTRY
        from compiler.registry.namespace_data import event_satisfies
    except ImportError as exc:  # pragma: no cover - depends on external checkout
        raise EmulatorInputError(
            f"could not load tcl-lsp command registry: {exc}"
        ) from exc

    spec = _f5_catalog_spec(REGISTRY, command)
    if spec is None:  # pragma: no cover - registry contract guard
        raise EmulatorInputError(f"catalog command has no specification: {command}")
    requirements = spec.event_requires
    by_name = dict(event_inventory)
    preferred = [
        "HTTP_REQUEST",
        "CLIENT_ACCEPTED",
        "RULE_INIT",
        "SERVER_CONNECTED",
        "LB_SELECTED",
        "DNS_REQUEST",
        "ACCESS_POLICY_AGENT_EVENT",
        "AUTH_RESULT",
        "CLIENT_DATA",
        "SERVER_DATA",
    ]
    ordered_names: list[str] = []
    if requirements is not None and requirements.also_in:
        ordered_names.extend(sorted(requirements.also_in))
    ordered_names.extend(name for name in preferred if name not in ordered_names)
    ordered_names.extend(name for name, _ in event_inventory if name not in ordered_names)

    selected_name: str | None = None
    selected_props: Any | None = None
    hinted_event = _CANDIDATE_EVENT_HINTS.get(command)
    if hinted_event is not None and hinted_event in by_name:
        hinted_props = by_name[hinted_event]
        if requirements is None or event_satisfies(hinted_props, requirements, hinted_event):
            selected_name = hinted_event
            selected_props = hinted_props
    for name in ordered_names:
        if selected_name is not None:
            break
        props = by_name.get(name)
        if props is None:
            continue
        if requirements is None or event_satisfies(props, requirements, name):
            selected_name = name
            selected_props = props
            break
    if selected_name is None or selected_props is None:
        raise EmulatorInputError(
            f"catalog command has no target-valid event template: {command}"
        )

    profiles: list[str] = []

    def add_profile(name: str) -> None:
        if name and name not in profiles:
            profiles.append(name)

    transport = (
        requirements.transport
        if requirements is not None and requirements.transport is not None
        else selected_props.transport
    )
    if transport == "tcp" or isinstance(transport, tuple) and "tcp" in transport:
        add_profile("TCP")
    elif transport == "udp" or isinstance(transport, tuple) and "udp" in transport:
        add_profile("UDP")

    required_profiles = set(requirements.profiles) if requirements is not None else set()
    implied_profiles = set(selected_props.implied_profiles)
    profile_candidates = required_profiles | implied_profiles
    # HTTP and FASTHTTP are alternatives when they are merely implied by the
    # selected event. An explicit command requirement wins. If a command
    # explicitly requires FASTHTTP but the selected event is driven by HTTP,
    # retain both profiles so the reusable HTTP lifecycle can actually fire.
    if "HTTP" in required_profiles:
        add_profile("HTTP")
    if "FASTHTTP" in required_profiles:
        add_profile("FASTHTTP")
        if "HTTP" in implied_profiles:
            add_profile("HTTP")
    elif "HTTP" in profile_candidates:
        add_profile("HTTP")
    elif "FASTHTTP" in profile_candidates:
        add_profile("FASTHTTP")
    for profile in sorted(profile_candidates - {"HTTP", "FASTHTTP"}):
        add_profile(profile)
    for profile in _CANDIDATE_PROFILE_HINTS.get(command, ()):
        add_profile(profile)
    if not profiles and selected_name == "RULE_INIT":
        profiles.extend(DEFAULT_PROFILES)

    return {
        "event": selected_name,
        "profiles": profiles or list(DEFAULT_PROFILES),
        "args": [],
        "argument_policy": "collector-must-select-command-specific-arguments",
        "argument_source": "catalog.documentation.synopsis",
        "requires_fixture_state": selected_name != "RULE_INIT",
    }


