def _candidate_synopsis_words(synopsis: str, command: str) -> list[tuple[str, bool]]:
    """Extract one conservative, first-alternative argument shape from a synopsis."""
    text = synopsis.strip()
    if text.startswith(command):
        text = text[len(command) :].strip()
    raw_tokens = _CANDIDATE_SYNOPSIS_TOKEN_RE.findall(text)
    tokens: list[tuple[str, bool]] = []
    in_angle = False
    for token in raw_tokens:
        if token == "<":
            in_angle = True
        elif token == ">":
            in_angle = False
        elif token in {"(", ")", "|", "?", "+", "*", "#"}:
            tokens.append((token, False))
        else:
            tokens.append((token, in_angle))

    def parse_group(index: int, stop_at_close: bool) -> tuple[list[tuple[str, bool]], int]:
        branches: list[list[tuple[str, bool]]] = [[]]
        while index < len(tokens):
            token, placeholder = tokens[index]
            if token == ")" and stop_at_close:
                return branches[0], index + 1
            if token == "|":
                branches.append([])
                index += 1
                continue
            if token == "(":
                nested, index = parse_group(index + 1, True)
                branches[-1].extend(nested)
                continue
            if token not in {"<", ">", "?", "+", "*", "#", ")"}:
                branches[-1].append((token, placeholder))
            index += 1
        return branches[0], index

    words, _ = parse_group(0, False)
    return [
        (token, placeholder)
        for token, placeholder in words
        if token.lower() not in _CANDIDATE_SKIP_WORDS and token != "..."
    ][:COMMAND_PROBE_MAX_ARGS]


def _candidate_argument_value(
    token: str,
    placeholder: bool,
    command: str,
    index: int,
) -> str:
    """Turn a catalog synopsis token into a bounded, non-secret fixture value."""
    del index
    clean = token.strip("'\"")
    key = clean.lower().replace("-", "_")
    if not placeholder and key in _CANDIDATE_LITERAL_WORDS:
        return clean
    if not placeholder and clean.startswith("-"):
        return clean
    if not placeholder and not clean.isupper():
        return clean

    if key in {"enable", "disable", "on", "off", "up", "down", "get", "set", "clear"}:
        return clean
    if key in {
        "addr", "address", "ip", "ip_addr", "ip_address", "client_addr", "server_addr",
        "remote_addr", "local_addr", "source_addr", "destination_addr", "src", "dst",
        "node_addr", "node_address",
    }:
        return "192.0.2.10"
    if key in {"port", "client_port", "server_port", "remote_port", "local_port"}:
        return "80"
    if key in {"pool", "pool_name", "pool_obj", "pool_object"}:
        return "api_pool"
    if key in {"host", "hostname", "virtual_server", "virtual", "vs"}:
        return "example.test" if key in {"host", "hostname"} else "/Common/irule-test-vs"
    if key in {"uri", "path", "url", "query", "query_string"}:
        return "/testcl/command" if key in {"uri", "path"} else "https://example.test/"
    if key in {"method", "http_method"}:
        return "GET"
    if key in {"name", "username", "user", "user_name", "alias", "session_id", "id"}:
        return "testcl"
    if key in {"passphrase", "password", "secret", "key"}:
        return "testcl-secret"
    if key in {"pattern", "regex", "regexp"}:
        return ".*"
    if key in {"boolean", "bool", "flag", "bool_value"}:
        return "enable"
    if key in {
        "number", "integer", "count", "length", "size", "offset", "index", "seconds",
        "content_length", "nonnegative_integer",
        "timeout", "ttl", "code", "status_code", "priority", "weight", "limit",
        "collect_bytes", "skip_bytes", "idle_time", "keep_alive_interval", "buffer_size",
        "window_size", "tcp_ignore_rate", "tcp_ignore_burst",
    }:
        return "1"
    if key == "tcp_rexmt_thresh_value":
        return "3"
    if key == "tcp_max_segment_size":
        return "1200"
    if key in {"type", "dns_type", "rr_type"} and command.startswith("DNS"):
        return "A"
    if key in {"status", "action"}:
        return "up"
    if key in {"data", "value", "string", "message", "payload", "body", "text"}:
        return "testcl"
    return "testcl"


def _candidate_args_from_synopsis(command: str, synopsis: str) -> list[str]:
    return [
        _candidate_argument_value(token, placeholder, command, index)
        for index, (token, placeholder) in enumerate(
            _candidate_synopsis_words(synopsis, command)
        )
    ]


def _command_argument_candidates(
    command: str, spec: Any
) -> list[dict[str, Any]]:
    """Build bounded argument variants from registry subcommand/synopsis metadata."""
    hinted_arguments = _CANDIDATE_ARGUMENT_HINTS.get(command)
    if hinted_arguments is not None:
        return [
            {
                "args": list(args),
                "source": "tmos-17.5-safe-argument-hint",
                "synopsis": f"{command} typed-safe fixture",
                "minimum_arity": len(args),
            }
            for args in hinted_arguments
        ]
    variants: list[dict[str, Any]] = []
    if spec.subcommands:
        for subcommand, sub_spec in spec.subcommands.items():
            synopsis = sub_spec.synopsis or f"{command} {subcommand}"
            args = _candidate_args_from_synopsis(command, synopsis)
            if not args or args[0] != subcommand:
                args.insert(0, subcommand)
            minimum = getattr(getattr(sub_spec, "arity", None), "min", 0)
            variants.append(
                {
                    "args": args[:COMMAND_PROBE_MAX_ARGS],
                    "source": "tcl-lsp.subcommand-synopsis",
                    "synopsis": synopsis,
                    "minimum_arity": minimum if isinstance(minimum, int) else 0,
                    "selector": subcommand,
                }
            )
    else:
        for form in spec.forms:
            synopsis = form.synopsis or command
            args = _candidate_args_from_synopsis(command, synopsis)
            minimum = getattr(getattr(form, "arity", None), "min", 0)
            variants.append(
                {
                    "args": args[:COMMAND_PROBE_MAX_ARGS],
                    "source": "tcl-lsp.form-synopsis",
                    "synopsis": synopsis,
                    "minimum_arity": minimum if isinstance(minimum, int) else 0,
                }
            )
    deduplicated: list[dict[str, Any]] = []
    seen: set[tuple[str, ...]] = set()
    for variant in sorted(
        variants,
        key=lambda item: (
            item["minimum_arity"],
            len(item["args"]),
            tuple(item["args"]),
            item.get("synopsis", ""),
        ),
    ):
        key = tuple(variant["args"])
        if key in seen:
            continue
        seen.add(key)
        deduplicated.append(variant)
        if len(deduplicated) >= BEHAVIOR_CANDIDATE_MAX_VARIANTS:
            break
    return deduplicated or [
        {
            "args": [],
            "source": "tcl-lsp.command-synopsis-missing",
            "synopsis": command,
            "minimum_arity": 0,
        }
    ]


def _candidate_fixture_scenario(command: str) -> dict[str, Any] | None:
    """Supply only generic, non-secret state useful to local probe execution."""
    if command.startswith("IP::"):
        return {
            "ip": {
                "hops": 12,
                "intelligence": {"192.0.2.10": ["scanner", "proxy"]},
                "reputation": {"192.0.2.10": ["low-risk"]},
            }
        }
    if command.startswith("ACCESS::"):
        return {
            "access": {
                "acl_lookup": ["acl-testcl"],
                "acl_matched": ["acl-testcl"],
                "policy_agent_id": "agent-testcl",
                "policy_uri": True,
                "flow_id": "flow-testcl",
                "session_data": {
                    "session.user.name": "testcl",
                    "session.testcl": "value",
                },
                "perflow": {
                    "perflow.custom": "custom-value",
                    "perflow.scratchpad": "scratchpad-value",
                },
                "saml": {
                    "authn": "authn-testcl",
                    "assertion": "assertion-testcl",
                    "slo_req": "slo-req-testcl",
                    "slo_resp": "slo-resp-testcl",
                },
            }
        }
    if command.startswith("AUTH::"):
        return {
            "auth": {
                "result": "wantcredential",
                "response_data": {"token": "testcl"},
            }
        }
    if command.startswith("DNSMSG::"):
        return {
            "resolvers": {
                "testcl": [
                    {
                        "name": "example.com.",
                        "type": "A",
                        "class": "IN",
                        "ttl": 30,
                        "rdata": "192.0.2.10",
                    }
                ]
            }
        }
    if command.startswith("LB::") or command in {"active_members", "persist"}:
        return {
            "pools": {"api_pool": ["192.0.2.10:80"]},
            "backends": {"192.0.2.10:80": {"state": "up"}},
        }
    return None


def _capture_plan_probe_input(probe_input: dict[str, Any]) -> dict[str, Any]:
    """Return only fields that the external TMOS collector is allowed to consume."""
    allowed_fields = {"command", "args", "event", "profiles", "request"}
    return {
        field: value
        for field, value in probe_input.items()
        if field in allowed_fields
    }


def _build_behavior_vector_candidates(
    root: Path,
    packs: Any,
    offset: int,
    limit: int,
    *,
    namespace: str | None = None,
    runtime_status: str | None = None,
    variants: int = 1,
) -> dict[str, Any]:
    """Build an executable, reference-free plan for uncovered TMOS 17.5 commands."""
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise EmulatorInputError("behavior candidate offset must be a non-negative integer")
    if isinstance(limit, bool) or not isinstance(limit, int):
        raise EmulatorInputError("behavior candidate limit must be an integer")
    if not 1 <= limit <= BEHAVIOR_CANDIDATE_MAX_COMMANDS:
        raise EmulatorInputError(
            "behavior candidate limit must be between 1 and "
            f"{BEHAVIOR_CANDIDATE_MAX_COMMANDS}"
        )
    if isinstance(variants, bool) or not isinstance(variants, int):
        raise EmulatorInputError("behavior candidate variants must be an integer")
    if not 1 <= variants <= BEHAVIOR_CANDIDATE_MAX_VARIANTS:
        raise EmulatorInputError(
            "behavior candidate variants must be between 1 and "
            f"{BEHAVIOR_CANDIDATE_MAX_VARIANTS}"
        )
    if namespace is not None and (not isinstance(namespace, str) or not namespace):
        raise EmulatorInputError("behavior candidate namespace must be a non-empty string")
    if runtime_status is not None and runtime_status not in RUNTIME_STATUS_VALUES:
        raise EmulatorInputError(
            f"behavior candidate runtime status is unsupported: {runtime_status}"
        )

    coverage = _build_behavior_coverage(root, packs)
    uncovered = [
        command["name"]
        for command in coverage["commands"]
        if not command["covered"]
        and command["target_status"] == "available-in-tmos-17.5"
        and (namespace is None or command["namespace"] == namespace)
        and (runtime_status is None or command["runtime_status"] == runtime_status)
    ]
    start = min(offset, len(uncovered))
    selected_names = uncovered[start : start + limit]
    if len(selected_names) * variants > BEHAVIOR_CANDIDATE_MAX_PLAN_OBSERVATIONS:
        raise EmulatorInputError(
            "behavior candidate chunk would create more than "
            f"{BEHAVIOR_CANDIDATE_MAX_PLAN_OBSERVATIONS} capture observations; "
            "reduce limit or variants"
        )
    registry, _ = _runtime_status_map(root)
    event_inventory = _probe_event_inventory(root)
    candidate_rows: list[dict[str, Any]] = []
    observations: list[dict[str, Any]] = []
    status_counts: dict[str, int] = {}

    for command in selected_names:
        catalog = _command_probe_catalog_entry(root, command)
        row: dict[str, Any] = {
            "id": f"candidate:{command}",
            "command": command,
            "namespace": catalog["namespace"],
            "runtime_status": catalog["runtime_status"],
            "target_status": catalog["target_status"],
            "documentation": catalog["documentation"],
            "event_requirements": catalog["event_requirements"],
            "pure": catalog["pure"],
            "unsafe": catalog["unsafe"],
            "candidate_status": "unavailable-event-template",
            "argument_candidates": [],
            "input": None,
        }
        try:
            template = _command_probe_template(root, command, event_inventory)
            spec = _f5_catalog_spec(registry, command)
            if spec is None:
                raise EmulatorInputError(f"catalog command has no specification: {command}")
            argument_candidates = _command_argument_candidates(command, spec)
            primary = argument_candidates[0]
            probe_input: dict[str, Any] = {
                "command": command,
                "args": primary["args"],
                "event": template["event"],
                "profiles": template["profiles"],
            }
            state_hint = _CANDIDATE_STATE_HINTS.get(command)
            if state_hint is not None:
                if command.startswith("HTTP2::") and template["event"] in {
                    "HTTP_REQUEST",
                    "HTTP_RESPONSE",
                }:
                    probe_input["request"] = _http2_candidate_request()
                else:
                    probe_input["state"] = {
                        layer: dict(values) for layer, values in state_hint.items()
                    }
            else:
                request = _protocol_request_template(template["event"])
                if request is not None:
                    probe_input["request"] = request
            scenario = _candidate_fixture_scenario(command)
            if scenario is not None:
                probe_input["scenario"] = scenario
            _normalise_command_probe_request(
                root,
                probe_input,
                allow_external_protocol_request=True,
            )
            row.update(
                {
                    "candidate_status": "ready-for-reference-capture",
                    "event": template["event"],
                    "profiles": template["profiles"],
                    "input": probe_input,
                    "argument_candidates": argument_candidates,
                    "selected_argument_source": primary["source"],
                    "collector_action": (
                        "execute this command probe on TMOS 17.5 using the selected "
                        "event/profile fixture, then retain the observed output"
                    ),
                }
            )
            capture_variant_ids: list[str] = []
            for variant_index, argument_candidate in enumerate(
                argument_candidates[:variants]
            ):
                variant_input = dict(probe_input)
                variant_input["args"] = list(argument_candidate["args"])
                observation_id = row["id"] if variant_index == 0 else (
                    f"{row['id']}:variant:{variant_index + 1}"
                )
                capture_variant_ids.append(observation_id)
                observations.append(
                    {
                        "id": observation_id,
                        "operation": "command_probe",
                        "input": _capture_plan_probe_input(variant_input),
                        "comparisons": [
                            {
                                "label": "command status",
                                "actual_path": ["execution", "status"],
                                "reference_path": ["status"],
                            }
                        ],
                    }
                )
            row["capture_variant_count"] = len(capture_variant_ids)
            row["capture_observation_ids"] = capture_variant_ids
        except EmulatorInputError as exc:
            row["generation_error"] = str(exc)
        candidate_rows.append(row)

    plan = None
    if observations:
        plan = _normalise_capture_plan(
            root,
            {
                "schema_version": 1,
                "profile": "tmos-17.5",
                "name": f"tmos-17.5-behavior-candidates-{start:06d}-{len(observations):06d}",
                "source": "external-bigip-or-vlab",
                "provenance": {
                    "collector": "behavior-vector-candidate-generator",
                    "tmos_build": "17.5",
                    "capture_id": f"behavior-candidates-{start:06d}",
                    "generator": "tmos-17.5-behavior-vector-candidates-v1",
                },
                "observations": observations,
            },
        )
    for row in candidate_rows:
        status = row["candidate_status"]
        status_counts[status] = status_counts.get(status, 0) + 1
    status_counts = {
        status: count for status, count in status_counts.items() if count > 0
    }
    return {
        "status": "ok",
        "schema_version": 1,
        "profile": "tmos-17.5",
        "tmos_version": TMOS_VERSION,
        "source": "behavior-vector-candidates",
        "summary": {
            "uncovered_command_count": len(uncovered),
            "candidate_command_count": len(candidate_rows),
            "candidate_variant_count": sum(
                row.get("capture_variant_count", 0) for row in candidate_rows
            ),
            "plan_observation_count": len(observations),
            "candidate_status_counts": dict(sorted(status_counts.items())),
            "coverage": {
                key: coverage["summary"][key]
                for key in (
                    "target_f5_command_count",
                    "covered_command_count",
                    "uncovered_command_count",
                    "coverage_percent",
                )
            },
        },
        "chunk": {
            "offset": offset,
            "limit": limit,
            "variants": variants,
            "count": len(selected_names),
            "total": len(uncovered),
            "has_more": start + len(selected_names) < len(uncovered),
        },
        "interpretation": (
            "Candidates are registry-derived invocation hypotheses supplemented by "
            "bounded TMOS-safe type hints and a reference-free capture plan. They are "
            "syntactically executable through the local probe path, but their results "
            "are not TMOS 17.5 evidence until collected externally."
        ),
        "candidates": candidate_rows,
        "capture_plan": plan,
    }


def _build_behavior_vector_sweep(
    root: Path,
    packs: Any,
    offset: int,
    limit: int,
    *,
    namespace: str | None = None,
    runtime_status: str | None = None,
    variants: int = 1,
) -> dict[str, Any]:
    """Execute one bounded candidate chunk locally and return compact evidence."""
    if isinstance(limit, bool) or not isinstance(limit, int):
        raise EmulatorInputError("behavior sweep limit must be an integer")
    if not 1 <= limit <= BEHAVIOR_SWEEP_MAX_COMMANDS:
        raise EmulatorInputError(
            "behavior sweep limit must be between 1 and "
            f"{BEHAVIOR_SWEEP_MAX_COMMANDS}"
        )
    if isinstance(variants, bool) or not isinstance(variants, int):
        raise EmulatorInputError("behavior sweep variants must be an integer")
    if not 1 <= variants <= BEHAVIOR_CANDIDATE_MAX_VARIANTS:
        raise EmulatorInputError(
            "behavior sweep variants must be between 1 and "
            f"{BEHAVIOR_CANDIDATE_MAX_VARIANTS}"
        )
    candidates = _build_behavior_vector_candidates(
        root,
        packs,
        offset,
        limit,
        namespace=namespace,
        runtime_status=runtime_status,
        variants=variants,
    )
    rows: list[dict[str, Any]] = []
    status_counts: dict[str, int] = {}
    execution_status_counts = {"ok": 0, "error": 0, "profile-gated": 0}
    for candidate in candidates["candidates"]:
        row = {
            "id": candidate["id"],
            "command": candidate["command"],
            "event": candidate.get("event"),
            "profiles": candidate.get("profiles", []),
            "args": (
                candidate["input"].get("args", [])
                if isinstance(candidate.get("input"), dict)
                else None
            ),
            "candidate_status": candidate["candidate_status"],
            "sweep_status": "candidate-unavailable",
            "variants": [],
        }
        probe_input = candidate.get("input")
        if not isinstance(probe_input, dict):
            if candidate.get("generation_error"):
                row["error"] = candidate["generation_error"]
            rows.append(row)
            status_counts["candidate-unavailable"] = (
                status_counts.get("candidate-unavailable", 0) + 1
            )
            continue
        argument_candidates = candidate.get("argument_candidates", [])
        if not isinstance(argument_candidates, list) or not argument_candidates:
            argument_candidates = [{"args": [], "source": "candidate-fallback"}]
        for argument_candidate in argument_candidates[:variants]:
            args = argument_candidate.get("args")
            if not isinstance(args, list):
                args = []
            variant = {
                "args": list(args),
                "source": argument_candidate.get("source", "candidate"),
                "sweep_status": "input-error",
            }
            variant_input = dict(probe_input)
            variant_input["args"] = list(args)
            try:
                result = run_command_probe(
                    variant_input,
                    tcl_lsp_root=str(root),
                    allow_external_protocol_request=True,
                )
                execution = result.get("execution")
                if not isinstance(execution, dict):
                    raise EmulatorInputError(
                        "command probe returned no execution object"
                    )
                sweep_status = _catalog_smoke_status(execution)
                variant.update(
                    {
                        "sweep_status": sweep_status,
                        "execution": _catalog_smoke_execution_snapshot(execution),
                    }
                )
                execution_status = execution.get("status")
                if execution_status in execution_status_counts:
                    execution_status_counts[execution_status] += 1
            except (EmulatorInputError, OSError) as exc:
                variant["error"] = str(exc)[:2048]
            row["variants"].append(variant)
            status = variant["sweep_status"]
            status_counts[status] = status_counts.get(status, 0) + 1
        if row["variants"]:
            primary_variant = row["variants"][0]
            row["sweep_status"] = primary_variant["sweep_status"]
            if "execution" in primary_variant:
                row["execution"] = primary_variant["execution"]
            if "error" in primary_variant:
                row["error"] = primary_variant["error"]
        rows.append(row)

    candidate_summary = candidates["summary"]
    return {
        "status": "ok",
        "schema_version": 1,
        "profile": "tmos-17.5",
        "tmos_version": TMOS_VERSION,
        "source": "behavior-vector-local-sweep",
        "interpretation": (
            "This sweep executes registry-derived candidates against the local "
            "emulator. It is useful for finding dispatch, fixture, and semantic "
            "failures, but it is not independent TMOS 17.5 evidence."
        ),
        "summary": {
            "uncovered_command_count": candidate_summary["uncovered_command_count"],
            "candidate_command_count": len(rows),
            "variant_count": sum(len(row["variants"]) for row in rows),
            "executed_count": sum(
                count
                for status, count in status_counts.items()
                if status not in {"candidate-unavailable", "input-error"}
            ),
            "status_counts": dict(sorted(status_counts.items())),
            "execution_status_counts": execution_status_counts,
            "coverage": candidate_summary["coverage"],
        },
        "chunk": candidates["chunk"],
        "candidates": rows,
        "capture_plan": candidates["capture_plan"],
    }


def _protocol_request_template(event: str) -> dict[str, Any] | None:
    """Return a bounded starter fixture for the reusable protocol driver."""
    if event in {"HTTP_REQUEST", "HTTP_RESPONSE"}:
        return {
            "method": "GET",
            "uri": "/testcl/command",
            "host": "example.test",
        }
    if event.startswith("DNS_"):
        return {
            "qname": "example.com",
            "qtype": "A",
            "recursion_desired": True,
        }
    if event.startswith("MQTT_"):
        return {
            "client_id": "testcl-1705",
            "topic": "testcl/command",
            "payload": "testcl",
        }
    if event.startswith("SIP_"):
        return {
            "method": "OPTIONS",
            "uri": "sip:test@example.invalid",
        }
    if event.startswith("RTSP_"):
        return {
            "method": "DESCRIBE",
            "uri": "rtsp://example.test/live",
            "version": "RTSP/1.0",
            "headers": {"CSeq": "1"},
        }
    if event == "ICAP_REQUEST":
        return {
            "icap": {
                "method": "REQMOD",
                "uri": "icap://example.test/reqmod",
                "headers": {"Host": "example.test"},
            }
        }
    if event == "ICAP_RESPONSE":
        return {
            "icap": {
                "status": 204,
                "headers": {"ISTag": "testcl-1705"},
            }
        }
    if event == "TDS_REQUEST":
        return {"tds": {"type": 1, "sqltext": "select 1"}}
    if event == "TDS_RESPONSE":
        return {"tds": {"type": 4}}
    if event in {"FIX_HEADER", "FIX_MESSAGE"}:
        return {
            "fix": {
                "tags": {
                    "35": "D",
                    "49": "testcl",
                    "56": "target",
                    "11": "order-1",
                }
            }
        }
    if event == "WS_REQUEST":
        return {
            "websocket": {
                "method": "GET",
                "uri": "/socket",
                "host": "example.test",
                "sec_websocket_key": "dGhlIHNhbXBsZSBub25jZQ==",
            }
        }
    if event == "PCP_REQUEST":
        return {
            "pcp": {
                "opcode": "map",
                "lifetime": 3600,
                "protocol": "tcp",
                "internal_port": 22,
                "suggested_ext_port": 40000,
                "suggested_ext_addr": "0.0.0.0",
            }
        }
    if event in {"RADIUS_AAA_AUTH_REQUEST", "RADIUS_AAA_ACCT_REQUEST"}:
        return {
            "radius": {
                "code": 4 if event.endswith("ACCT_REQUEST") else 1,
                "id": 23,
                "authenticator_hex": "00" * 16,
                "avps": [
                    {"code": "User-Name", "data": "testcl"},
                ],
            }
        }
    return None


def _build_capture_plan_template(
    root: Path,
    offset: int,
    limit: int,
    *,
    namespace: str | None = None,
    runtime_status: str | None = None,
    target_status: str | None = "available-in-tmos-17.5",
    name: str | None = None,
    source: str = "external-bigip-or-vlab",
    collector: str = "external-collector",
    tmos_build: str = "17.5",
    capture_id: str | None = None,
) -> dict[str, Any]:
    """Emit an assembly-ready plan template for one runnable catalog chunk."""
    if not 1 <= limit <= CAPTURE_MAX_RECORDS:
        raise EmulatorInputError(
            "capture plan template limit must be between 1 and "
            f"{CAPTURE_MAX_RECORDS}"
        )
    if target_status not in (None, "available-in-tmos-17.5"):
        raise EmulatorInputError(
            "capture plan templates only include commands available in TMOS 17.5"
        )
    campaign = _build_capture_campaign(
        root,
        offset,
        limit,
        namespace=namespace,
        runtime_status=runtime_status,
        target_status="available-in-tmos-17.5",
    )
    event_inventory = _probe_event_inventory(root)
    campaign_data = campaign["campaign"]
    if not campaign_data["cases"]:
        raise EmulatorInputError(
            "capture plan template offset is past the available TMOS 17.5 commands"
        )
    observations: list[dict[str, Any]] = []
    for case in campaign_data["cases"]:
        template = _command_probe_template(root, case["name"], event_inventory)
        protocol_request = _protocol_request_template(template["event"])
        probe_input = {
            "command": case["name"],
            "args": template["args"],
            "event": template["event"],
            "profiles": template["profiles"],
        }
        if protocol_request is not None:
            probe_input["request"] = protocol_request
        observations.append(
            {
                "id": case["id"],
                "operation": "command_probe",
                "input": probe_input,
                "comparisons": [
                    {
                        "label": "command status",
                        "actual_path": ["execution", "status"],
                        "reference_path": ["status"],
                    }
                ],
            }
        )

    plan = {
        "schema_version": 1,
        "profile": "tmos-17.5",
        "name": name or f"tmos-17.5-capture-plan-{offset:06d}-{limit:06d}",
        "source": source,
        "provenance": {
            "collector": collector,
            "tmos_build": tmos_build,
            "capture_id": capture_id or f"campaign-{offset:06d}-{limit:06d}",
            "generator": "tmos-17.5-capture-plan-template-v1",
        },
        "observations": observations,
    }
    # Validate before returning so a generated plan is safe to send directly
    # to the assembly boundary. This also catches long command-derived IDs.
    return _normalise_capture_plan(root, plan)


def _build_runtime_probe(
    root: Path,
    offset: int,
    limit: int,
    *,
    namespace: str | None = None,
    runtime_status: str | None = None,
    target_status: str | None = None,
) -> dict[str, Any]:
    """Return live dispatch-registration evidence for one catalog chunk."""
    capabilities = _build_capabilities(
        root,
        offset,
        limit,
        namespace=namespace,
        runtime_status=runtime_status,
        target_status=target_status,
    )
    capability_commands = capabilities["commands"]
    command_names = [command["name"] for command in capability_commands]

    probe_rows: list[dict[str, Any]] = []
    if command_names:
        session = EmulatorSession(
            root,
            {"irule": "when RULE_INIT {}", "profiles": ["TCP", "HTTP"]},
            allow_irule_file=False,
            allow_requests=False,
            allow_packets=False,
            backend="inprocess",
        )
        try:
            probe_rows = session.probe_runtime_commands(command_names)
        finally:
            session.close()

    rows_by_name = {row["name"]: row for row in probe_rows}
    if len(rows_by_name) != len(capability_commands):
        raise EmulatorInputError("runtime probe did not return one row per catalog command")
    commands = [
        {
            "name": command["name"],
            "namespace": command["namespace"],
            "runtime_status": command["runtime_status"],
            "target_status": command["target_status"],
            "pure": command["pure"],
            "unsafe": command["unsafe"],
            "registered": rows_by_name[command["name"]]["registered"],
            "resolved_handler": rows_by_name[command["name"]]["resolved_handler"],
        }
        for command in capability_commands
    ]
    registered_count = sum(1 for command in commands if command["registered"])
    summary = dict(capabilities["summary"])
    summary.update(
        {
            "probed_count": len(commands),
            "registered_count": registered_count,
            "unregistered_count": len(commands) - registered_count,
            "registration_status_counts": {
                "registered": registered_count,
                "unregistered": len(commands) - registered_count,
            },
        }
    )
    return {
        "status": "ok",
        "schema_version": 1,
        "profile": "tmos-17.5",
        "tmos_version": TMOS_VERSION,
        "source": capabilities["source"],
        "probe": {
            "method": "::itest::_command_map",
            "operation": "dispatch-registration",
            "executes_catalog_commands": False,
            "interpretation": (
                "registered confirms that the live iRule dispatcher resolves "
                "the catalog name; it does not prove BIG-IP/TMM semantic parity"
            ),
        },
        "summary": summary,
        "chunk": capabilities["chunk"],
        "filter": capabilities["filter"],
        "commands": commands,
    }


def _catalog_smoke_status(execution: dict[str, Any]) -> str:
    """Classify a zero-argument command result without calling it semantic parity."""
    status = execution.get("status")
    if status == "ok":
        return "ok"
    if status == "profile-gated":
        return "profile-gated"
    if status != "error":
        return "runtime-error"
    error = str(execution.get("error", "")).lower()
    if (
        "wrong # args" in error
        or "wrong number of arguments" in error
        or "requires a subcommand" in error
        or "requires an argument" in error
        or "missing required" in error
    ):
        return "argument-required"
    return "runtime-error"


def _catalog_smoke_execution_snapshot(execution: dict[str, Any]) -> dict[str, Any]:
    """Keep catalog smoke output bounded while retaining actionable evidence."""
    raw_value = execution.get("value")
    value = str(raw_value) if raw_value is not None else ""
    snapshot: dict[str, Any] = {
        "status": execution.get("status"),
        "tcl_return_code": execution.get("tcl_return_code"),
        "value": value[:4096] if execution.get("status") == "ok" else None,
        "value_truncated": execution.get("status") == "ok" and len(value) > 4096,
        "value_bytes": execution.get("value_bytes", 0),
    }
    event = execution.get("event")
    if isinstance(event, dict):
        compact_event = {
            key: event[key]
            for key in ("mode", "event", "fired", "reason")
            if key in event
        }
        for key in ("events_fired", "decisions", "logs"):
            if key in event:
                values = event[key]
                compact_event[key] = values[:32] if isinstance(values, list) else values
        nested = event.get("result")
        if isinstance(nested, dict):
            compact_event["result"] = {
                key: nested[key]
                for key in (
                    "pool", "node", "response_committed", "connection_state",
                    "events_fired", "decisions", "logs",
                )
                if key in nested
            }
            response = nested.get("response")
            if isinstance(response, dict):
                compact_event["result"]["response"] = {
                    key: response[key]
                    for key in ("status", "reason")
                    if key in response
                }
            for key in ("events_fired", "decisions", "logs"):
                if key in compact_event["result"] and isinstance(
                    compact_event["result"][key], list
                ):
                    compact_event["result"][key] = compact_event["result"][key][:32]
        snapshot["event"] = compact_event
    if execution.get("status") == "error":
        snapshot["error"] = str(execution.get("error", ""))[:2048]
    return snapshot


def _build_catalog_smoke(
    root: Path,
    offset: int,
    limit: int,
    *,
    namespace: str | None = None,
    runtime_status: str | None = None,
    target_status: str | None = "available-in-tmos-17.5",
) -> dict[str, Any]:
    """Execute bounded zero-argument probes for one target catalog chunk.

    This is intentionally a smoke test, not a generated argument solver. It
    measures whether a catalog command can dispatch and return with the
    deterministic fixture selected from its event requirements. Commands that
    need arguments remain useful results: they are reported as
    ``argument-required`` for the next behavior-vector pass.
    """
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise EmulatorInputError("catalog smoke offset must be a non-negative integer")
    if isinstance(limit, bool) or not isinstance(limit, int):
        raise EmulatorInputError("catalog smoke limit must be an integer")
    if not 1 <= limit <= CATALOG_SMOKE_MAX_COMMANDS:
        raise EmulatorInputError(
            "catalog smoke limit must be between 1 and "
            f"{CATALOG_SMOKE_MAX_COMMANDS}"
        )
    if target_status is None:
        target_status = "available-in-tmos-17.5"
    probe = _build_runtime_probe(
        root,
        offset,
        limit,
        namespace=namespace,
        runtime_status=runtime_status,
        target_status=target_status,
    )
    event_inventory = _probe_event_inventory(root)
    rows: list[dict[str, Any]] = []
    status_counts: dict[str, int] = {}
    execution_status_counts = {"ok": 0, "error": 0, "profile-gated": 0}

    for command in probe["commands"]:
        row = {
            "name": command["name"],
            "namespace": command["namespace"],
            "runtime_status": command["runtime_status"],
            "target_status": command["target_status"],
            "registered": command["registered"],
            "resolved_handler": command["resolved_handler"],
            "pure": command["pure"],
            "unsafe": command["unsafe"],
            "smoke_status": None,
        }
        if not command["registered"]:
            row["smoke_status"] = "unregistered"
            rows.append(row)
            status_counts["unregistered"] = status_counts.get("unregistered", 0) + 1
            continue
        if command["target_status"] != "available-in-tmos-17.5":
            row["smoke_status"] = "skipped-target"
            rows.append(row)
            status_counts["skipped-target"] = status_counts.get("skipped-target", 0) + 1
            continue
        if command["unsafe"]:
            row["smoke_status"] = "skipped-unsafe"
            rows.append(row)
            status_counts["skipped-unsafe"] = status_counts.get("skipped-unsafe", 0) + 1
            continue

        try:
            template = _command_probe_template(root, command["name"], event_inventory)
            row.update(
                {
                    "event": template["event"],
                    "profiles": template["profiles"],
                    "args": [],
                }
            )
            request: dict[str, Any] = {
                "command": command["name"],
                "args": [],
                "event": template["event"],
                "profiles": template["profiles"],
            }
            protocol_request = _protocol_request_template(template["event"])
            if protocol_request is not None:
                request["request"] = protocol_request
            result = run_command_probe(
                request,
                tcl_lsp_root=str(root),
                allow_external_protocol_request=True,
            )
            execution = result["execution"]
            smoke_status = _catalog_smoke_status(execution)
            row.update(
                {
                    "execution": _catalog_smoke_execution_snapshot(execution),
                    "smoke_status": smoke_status,
                }
            )
            execution_status = execution.get("status")
            if execution_status in execution_status_counts:
                execution_status_counts[execution_status] += 1
        except (EmulatorInputError, OSError) as exc:
            row.update(
                {
                    "smoke_status": "fixture-error",
                    "error": str(exc),
                }
            )
        rows.append(row)
        status_counts[row["smoke_status"]] = status_counts.get(row["smoke_status"], 0) + 1

    summary = dict(probe["summary"])
    summary.update(
        {
            "smoke_count": len(rows),
            "executed_count": sum(
                1
                for row in rows
                if row["smoke_status"]
                in {"ok", "argument-required", "runtime-error", "profile-gated"}
            ),
            "behavioral_ok_count": status_counts.get("ok", 0),
            "argument_required_count": status_counts.get("argument-required", 0),
            "status_counts": dict(sorted(status_counts.items())),
            "execution_status_counts": execution_status_counts,
        }
    )
    return {
        "status": "ok",
        "schema_version": 1,
        "profile": "tmos-17.5",
        "tmos_version": TMOS_VERSION,
        "probe": {
            "method": "generated-command-probe",
            "operation": "zero-argument-smoke",
            "args": [],
            "unsafe_commands_skipped": True,
            "interpretation": (
                "ok proves the generated fixture completed in the emulator; "
                "it is not a claim of TMOS semantic parity"
            ),
        },
        "summary": summary,
        "chunk": probe["chunk"],
        "filter": probe["filter"],
        "commands": rows,
    }


def _command_probe_catalog_entry(root: Path, command: Any) -> dict[str, Any]:
    """Resolve one target-valid F5 command for the command workbench."""
    if not isinstance(command, str) or not command:
        raise EmulatorInputError("command probe command must be a non-empty string")

    _load_session_class(root)
    try:
        from compiler.registry import REGISTRY
    except ImportError as exc:  # pragma: no cover - depends on external checkout
        raise EmulatorInputError(f"could not load tcl-lsp command registry: {exc}") from exc

    if command not in set(_f5_catalog_command_names(REGISTRY)):
        raise EmulatorInputError(
            f"command probe requires a command from the pinned F5 catalog: {command}"
        )
    spec = _f5_catalog_spec(REGISTRY, command)
    if spec is None:  # pragma: no cover - registry contract guard
        raise EmulatorInputError(f"catalog command has no specification: {command}")
    catalog_kind = _catalog_kind(command, spec)
    if catalog_kind != "f5-irule":
        raise EmulatorInputError(
            f"command probe accepts F5 iRule commands only, not {catalog_kind}: {command}"
        )
    target_status = _target_status(
        command,
        TMOS_17_5_POST_TARGET_COMMANDS,
        TMOS_17_5_UNAVAILABLE_COMMANDS,
    )
    if target_status != "available-in-tmos-17.5":
        raise EmulatorInputError(
            f"command is {target_status}: {command}"
        )

    tcl_dir = root / "tooling" / "irule_test" / "tcl"
    runtime_status = _capability_status(
        _mock_proc_name(command),
        _proc_names(tcl_dir / "command_mocks.tcl"),
        _proc_names(tcl_dir / "_mock_stubs.tcl"),
    )
    requirement = spec.event_requires
    hover = getattr(spec, "hover", None)
    return {
        "name": command,
        "namespace": command.split("::", 1)[0] if "::" in command else "",
        "catalog_kind": catalog_kind,
        "subcommands": sorted(spec.subcommands),
        "documentation": {
            "summary": getattr(hover, "summary", "") if hover else "",
            "synopsis": list(getattr(hover, "synopsis", ()) or ()) if hover else [],
            "return_value": getattr(hover, "return_value", "") if hover else "",
            "source": getattr(hover, "source", "") if hover else "",
        },
        "pure": bool(spec.pure),
        "unsafe": bool(spec.unsafe),
        "runtime_status": runtime_status,
        "target_status": target_status,
        "event_requirements": {
            "profiles": sorted(requirement.profiles) if requirement else [],
            "also_in": sorted(requirement.also_in) if requirement else [],
            "transport": requirement.transport if requirement else None,
            "capability": requirement.capability if requirement else None,
            "client_side": bool(requirement.client_side) if requirement else False,
            "server_side": bool(requirement.server_side) if requirement else False,
            "flow": bool(requirement.flow) if requirement else False,
            "init_only": bool(requirement.init_only) if requirement else False,
        },
    }


def _normalise_command_probe_args(value: Any) -> list[str]:
    """Convert JSON scalar arguments into bounded, substitution-free Tcl words."""
    if value is None:
        return []
    if not isinstance(value, list):
        raise EmulatorInputError("command probe args must be an array of scalar values")
    if len(value) > COMMAND_PROBE_MAX_ARGS:
        raise EmulatorInputError(
            f"command probe accepts at most {COMMAND_PROBE_MAX_ARGS} arguments"
        )

    result: list[str] = []
    total_bytes = 0
    for index, item in enumerate(value):
        if isinstance(item, bool):
            text = "1" if item else "0"
        elif isinstance(item, (str, int, float)):
            if isinstance(item, float) and not math.isfinite(item):
                raise EmulatorInputError(
                    f"command probe arg {index} must be finite"
                )
            text = str(item)
        else:
            raise EmulatorInputError(
                f"command probe arg {index} must be a string, number, or boolean"
            )
        if "\x00" in text:
            raise EmulatorInputError(f"command probe arg {index} must not contain NUL")
        size = len(text.encode("utf-8"))
        if size > COMMAND_PROBE_MAX_ARG_BYTES:
            raise EmulatorInputError(
                f"command probe arg {index} exceeds {COMMAND_PROBE_MAX_ARG_BYTES} UTF-8 bytes"
            )
        total_bytes += size
        if total_bytes > COMMAND_PROBE_MAX_TOTAL_ARG_BYTES:
            raise EmulatorInputError(
                "command probe arguments exceed the 64 KiB total limit"
            )
        result.append(text)
    return result


def _command_probe_irule(event: str, command: str, args: list[str]) -> str:
    """Build the fixed event wrapper used by the safe command workbench."""
    command_words = " ".join([_tcl_quote(command), *(_tcl_quote(arg) for arg in args)])
    fixture_setup = ""
    if command.startswith("AUTH::"):
        # AUTH session commands require a deterministic AUTH_ID. Configure the
        # fixture to pause at AUTH_WANTCREDENTIAL so continuation and prompt
        # access have a valid preceding lifecycle state.
        fixture_setup = "set ::orch::_testcl_auth_fixture [AUTH::start pam default_radius]\n    "
        if command == "AUTH::response_data":
            fixture_setup += (
                "AUTH::subscribe $::orch::_testcl_auth_fixture\n    "
                "AUTH::authenticate $::orch::_testcl_auth_fixture\n    "
            )
        elif command in {
            "AUTH::authenticate_continue",
            "AUTH::wantcredential_prompt",
            "AUTH::wantcredential_prompt_style",
            "AUTH::wantcredential_type",
        }:
            fixture_setup += "AUTH::authenticate $::orch::_testcl_auth_fixture\n    "
    elif command.startswith("X509::") and command != "X509::verify_cert_error_string":
        # X509 utilities consume the opaque handle returned by SSL::cert. The
        # candidate state fixture supplies one peer certificate at index zero.
        fixture_setup = "set ::orch::_testcl_x509_fixture [SSL::cert 0]\n    "
    elif command.startswith("DNSMSG::"):
        # DNSMSG commands consume opaque handles returned by
        # RESOLVER::name_lookup. Create deterministic handles in the same
        # event before probing the candidate invocation.
        fixture_setup = (
            "set ::orch::_testcl_dnsmsg_fixture "
            "[RESOLVER::name_lookup testcl example.com. A]\n    "
        )
    elif command.startswith("ACCESS::"):
        # ACCESS session/user commands need an existing policy session. Keep
        # this setup inside the generated event so each candidate variant gets
        # a fresh sid-1 without leaking state across probes.
        fixture_setup = (
            "set ::orch::_testcl_access_sid [ACCESS::session create -flow]\n    "
        )
        if command == "ACCESS::user":
            fixture_setup += (
                "set ::orch::_testcl_access_user_key "
                "[ACCESS::user getkey testcl-hash]\n    "
            )
        elif command == "ACCESS::ephemeral-auth":
            fixture_setup += (
                "set ::orch::_testcl_access_ephemeral_password "
                "[ACCESS::ephemeral-auth create -user testcl -sid $::orch::_testcl_access_sid]\n    "
            )
    return f"""when {event} {{
    {fixture_setup}set ::orch::_testcl_command_probe_rc [catch {{
        set ::orch::_testcl_command_probe_value [{command_words}]
    }} ::orch::_testcl_command_probe_error ::orch::_testcl_command_probe_options]
}}
"""


def _normalise_protocol_request(event: str, request: Any) -> dict[str, Any]:
    """Validate the bounded, external-only request sent to a protocol driver."""
    if not isinstance(request, dict):
        raise EmulatorInputError("protocol driver request must be a JSON object")
    if len(request) > PROTOCOL_REQUEST_MAX_FIELDS:
        raise EmulatorInputError(
            f"protocol driver request accepts at most {PROTOCOL_REQUEST_MAX_FIELDS} fields"
        )
    unknown = sorted(
        str(field) for field in request if field not in PROTOCOL_REQUEST_FIELDS
    )
    if unknown:
        raise EmulatorInputError(
            "unsupported protocol driver request field(s): " + ", ".join(unknown)
        )
    try:
        request_bytes = len(
            json.dumps(request, ensure_ascii=False, allow_nan=False, separators=(",", ":"))
            .encode("utf-8")
        )
    except (TypeError, ValueError, OverflowError, UnicodeEncodeError) as exc:
        raise EmulatorInputError(
            "protocol driver request must contain only finite JSON-compatible UTF-8 data"
        ) from exc
    if request_bytes > PROTOCOL_REQUEST_MAX_BYTES:
        raise EmulatorInputError(
            f"protocol driver request exceeds the {PROTOCOL_REQUEST_MAX_BYTES // 1024} KiB limit"
        )

    text_fields = (
        "destination", "payload", "payload_base64", "qname", "qtype", "client_id", "topic",
        "message", "method", "uri", "version", "status", "body",
    )
    non_empty_text_fields = {
        "destination", "qname", "qtype", "client_id", "topic", "message", "method",
        "uri", "version", "status",
    }
    for field in text_fields:
        if field not in request:
            continue
        value = request[field]
        if not isinstance(value, str):
            raise EmulatorInputError(f"protocol driver request {field} must be a string")
        if field in non_empty_text_fields and not value:
            raise EmulatorInputError(
                f"protocol driver request {field} must be a non-empty string"
            )
        if "\x00" in value:
            raise EmulatorInputError(
                f"protocol driver request {field} must not contain NUL"
            )
        if field in {"destination", "method", "uri", "status"} and (
            "\r" in value or "\n" in value
        ):
            raise EmulatorInputError(
                f"protocol driver request {field} must not contain line breaks"
            )
        try:
            value_bytes = value.encode("utf-8")
        except UnicodeEncodeError as exc:
            raise EmulatorInputError(
                f"protocol driver request {field} must be valid UTF-8"
            ) from exc
        if len(value_bytes) > PROTOCOL_REQUEST_MAX_TEXT_BYTES:
            raise EmulatorInputError(
                f"protocol driver request {field} exceeds the "
                f"{PROTOCOL_REQUEST_MAX_TEXT_BYTES // 1024} KiB limit"
            )

    if "payload" in request and "payload_base64" in request:
        raise EmulatorInputError(
            "protocol driver request must use payload or payload_base64, not both"
        )
    if "payload_base64" in request:
        try:
            base64.b64decode(request["payload_base64"], validate=True)
        except (binascii.Error, ValueError) as exc:
            raise EmulatorInputError(
                "protocol driver request payload_base64 is not valid base64"
            ) from exc

    if "pcp" in request:
        if not isinstance(request["pcp"], dict):
            raise EmulatorInputError("protocol driver request pcp must be an object")
        if event != "PCP_REQUEST":
            raise EmulatorInputError(
                "protocol driver request pcp is supported only for PCP_REQUEST"
            )
        try:
            _normalise_packets(
                [
                    {
                        "protocol": "pcp",
                        "direction": "client_to_server",
                        "source": {"address": "192.0.2.10", "port": 53000},
                        "destination": {"address": "192.0.2.53", "port": PCP_PORT},
                        "pcp": request["pcp"],
                    }
                ]
            )
        except EmulatorInputError as exc:
            raise EmulatorInputError(
                f"protocol driver request pcp is invalid: {exc}"
            ) from exc
    if "radius" in request:
        if not isinstance(request["radius"], dict):
            raise EmulatorInputError("protocol driver request radius must be an object")
        if event not in {"RADIUS_AAA_AUTH_REQUEST", "RADIUS_AAA_ACCT_REQUEST"}:
            raise EmulatorInputError(
                "protocol driver request radius is supported only for RADIUS request events"
            )
        radius_request = request["radius"]
        if any(not isinstance(key, str) for key in radius_request):
            raise EmulatorInputError("protocol driver request radius field names must be strings")
        unknown_radius_fields = sorted(
            set(radius_request) - {"code", "id", "authenticator_hex", "avps"}
        )
        if unknown_radius_fields:
            raise EmulatorInputError(
                "protocol driver request radius unsupported field(s): "
                + ", ".join(unknown_radius_fields)
            )
        expected_code = (
            RADIUS_ACCOUNTING_REQUEST
            if event.endswith("ACCT_REQUEST")
            else RADIUS_AUTH_REQUEST
        )
        radius_code = radius_request.get("code", expected_code)
        if isinstance(radius_code, str):
            radius_code = RADIUS_REQUEST_CODE_NAMES.get(
                radius_code.lower(), radius_code
            )
        if radius_code != expected_code:
            raise EmulatorInputError(
                f"protocol driver request radius code does not match {event}"
            )
        try:
            _normalise_packets(
                [
                    {
                        "protocol": "radius",
                        "direction": "client_to_server",
                        "source": {"address": "192.0.2.10", "port": 53000},
                        "destination": {
                            "address": "192.0.2.53",
                            "port": 1813 if event.endswith("ACCT_REQUEST") else 1812,
                        },
                        "code": radius_code,
                        "id": radius_request.get("id", 0),
                        "authenticator_hex": radius_request.get(
                            "authenticator_hex", "00" * RADIUS_AUTHENTICATOR_BYTES
                        ),
                        "avps": radius_request.get("avps", []),
                    }
                ]
            )
        except (EmulatorInputError, AttributeError) as exc:
            raise EmulatorInputError(
                f"protocol driver request radius is invalid: {exc}"
            ) from exc
    if "ldap" in request:
        ldap_request = request["ldap"]
        if not isinstance(ldap_request, dict):
            raise EmulatorInputError("protocol driver request ldap must be an object")
        allowed_ldap_fields = {
            "operation", "message_id", "message_hex", "message_base64", "version", "dn",
            "password", "scope", "size_limit", "time_limit", "types_only", "attribute",
            "request_name", "request_value", "result_code", "diagnostic",
        }
        unknown_ldap_fields = sorted(set(ldap_request) - allowed_ldap_fields)
        if unknown_ldap_fields:
            raise EmulatorInputError(
                "protocol driver request ldap unsupported field(s): "
                + ", ".join(unknown_ldap_fields)
            )
        if event not in {"CLIENT_DATA", "SERVER_DATA"}:
            raise EmulatorInputError(
                "protocol driver request ldap is supported only for CLIENT_DATA and SERVER_DATA"
            )
        if "message_hex" in ldap_request and "message_base64" in ldap_request:
            raise EmulatorInputError(
                "protocol driver request ldap message_hex and message_base64 are mutually exclusive"
            )
        for field in ("dn", "password", "attribute", "request_name", "request_value", "diagnostic"):
            value = ldap_request.get(field)
            if value is not None:
                if not isinstance(value, str) or "\x00" in value:
                    raise EmulatorInputError(
                        f"protocol driver request ldap {field} must be a string without NUL"
                    )
                try:
                    if len(value.encode("utf-8")) > PROTOCOL_REQUEST_MAX_TEXT_BYTES:
                        raise EmulatorInputError(
                            f"protocol driver request ldap {field} is too long"
                        )
                except UnicodeEncodeError as exc:
                    raise EmulatorInputError(
                        f"protocol driver request ldap {field} must be valid UTF-8"
                    ) from exc
        if "types_only" in ldap_request and not isinstance(ldap_request["types_only"], bool):
            raise EmulatorInputError(
                "protocol driver request ldap types_only must be a boolean"
            )
        for field, minimum, maximum in (
            ("message_id", 0, 0x7FFF_FFFF),
            ("version", 0, 127),
            ("scope", 0, 2),
            ("size_limit", 0, 0x7FFF_FFFF),
            ("time_limit", 0, 0x7FFF_FFFF),
            ("result_code", 0, 0xFF),
        ):
            value = ldap_request.get(field)
            if value is not None and (
                isinstance(value, bool) or not isinstance(value, int) or not minimum <= value <= maximum
            ):
                raise EmulatorInputError(
                    f"protocol driver request ldap {field} must be an integer from {minimum} to {maximum}"
                )
        if "message_hex" in ldap_request:
            message_hex = ldap_request["message_hex"]
            if not isinstance(message_hex, str) or not message_hex or len(message_hex) % 2:
                raise EmulatorInputError(
                    "protocol driver request ldap message_hex must contain complete bytes"
                )
            try:
                raw_message = bytes.fromhex(message_hex)
            except ValueError as exc:
                raise EmulatorInputError(
                    "protocol driver request ldap message_hex must be hexadecimal"
                ) from exc
            if len(raw_message) > LDAP_MAX_MESSAGE_BYTES:
                raise EmulatorInputError(
                    "protocol driver request ldap message_hex exceeds the 2 MiB limit"
                )
        if "message_base64" in ldap_request:
            if not isinstance(ldap_request["message_base64"], str):
                raise EmulatorInputError(
                    "protocol driver request ldap message_base64 must be a string"
                )
            try:
                raw_message = base64.b64decode(ldap_request["message_base64"], validate=True)
            except (binascii.Error, ValueError) as exc:
                raise EmulatorInputError(
                    "protocol driver request ldap message_base64 is not valid base64"
                ) from exc
            if len(raw_message) > LDAP_MAX_MESSAGE_BYTES:
                raise EmulatorInputError(
                    "protocol driver request ldap message_base64 exceeds the 2 MiB limit"
                )
    if "fix" in request:
        fix_request = request["fix"]
        if not isinstance(fix_request, dict):
            raise EmulatorInputError("protocol driver request fix must be an object")
        allowed_fix_fields = {"message_hex", "message_base64", "begin_string", "tags"}
        unknown_fix_fields = sorted(set(fix_request) - allowed_fix_fields)
        if unknown_fix_fields:
            raise EmulatorInputError(
                "protocol driver request fix unsupported field(s): "
                + ", ".join(unknown_fix_fields)
            )
        if event not in {"CLIENT_DATA", "SERVER_DATA", "FIX_HEADER", "FIX_MESSAGE"}:
            raise EmulatorInputError(
                "protocol driver request fix is supported only for CLIENT_DATA, SERVER_DATA, FIX_HEADER, and FIX_MESSAGE"
            )
        if "message_hex" in fix_request and "message_base64" in fix_request:
            raise EmulatorInputError(
                "protocol driver request fix message_hex and message_base64 are mutually exclusive"
            )
        raw_fields = {"message_hex", "message_base64"} & set(fix_request)
        if raw_fields and set(fix_request) - raw_fields:
            raise EmulatorInputError(
                "protocol driver request fix raw message cannot be combined with structured fields"
            )
        if "message_hex" in fix_request:
            message_hex = fix_request["message_hex"]
            if not isinstance(message_hex, str) or not message_hex or len(message_hex) % 2:
                raise EmulatorInputError(
                    "protocol driver request fix message_hex must contain complete bytes"
                )
            try:
                raw_message = bytes.fromhex(message_hex)
            except ValueError as exc:
                raise EmulatorInputError(
                    "protocol driver request fix message_hex must be hexadecimal"
                ) from exc
            if len(raw_message) > FIX_MAX_MESSAGE_BYTES:
                raise EmulatorInputError(
                    "protocol driver request fix message_hex exceeds the 2 MiB limit"
                )
        if "message_base64" in fix_request:
            if not isinstance(fix_request["message_base64"], str):
                raise EmulatorInputError(
                    "protocol driver request fix message_base64 must be a string"
                )
            try:
                raw_message = base64.b64decode(
                    fix_request["message_base64"], validate=True
                )
            except (binascii.Error, ValueError) as exc:
                raise EmulatorInputError(
                    "protocol driver request fix message_base64 is not valid base64"
                ) from exc
            if len(raw_message) > FIX_MAX_MESSAGE_BYTES:
                raise EmulatorInputError(
                    "protocol driver request fix message_base64 exceeds the 2 MiB limit"
                )
        if "begin_string" in fix_request:
            begin_string = fix_request["begin_string"]
            if not isinstance(begin_string, str) or not begin_string:
                raise EmulatorInputError(
                    "protocol driver request fix begin_string must be a non-empty string"
                )
            try:
                begin_bytes = begin_string.encode("ascii")
            except UnicodeEncodeError as exc:
                raise EmulatorInputError(
                    "protocol driver request fix begin_string must contain ASCII bytes"
                ) from exc
            if (
                len(begin_bytes) > 256
                or b"=" in begin_bytes
                or any(byte < 0x20 or byte == 0x7F for byte in begin_bytes)
            ):
                raise EmulatorInputError(
                    "protocol driver request fix begin_string contains invalid bytes"
                )
        if "tags" in fix_request:
            tags = fix_request["tags"]
            if not isinstance(tags, dict) or not tags:
                raise EmulatorInputError(
                    "protocol driver request fix tags must be a non-empty object"
                )
            if len(tags) > FIX_MAX_FIELDS:
                raise EmulatorInputError(
                    f"protocol driver request fix tags cannot contain more than {FIX_MAX_FIELDS} fields"
                )
            canonical_tags: set[str] = set()
            for tag, value in tags.items():
                if not isinstance(tag, str) or not tag.isdigit() or len(tag) > 8:
                    raise EmulatorInputError(
                        "protocol driver request fix tag names must be decimal integers of at most 8 digits"
                    )
                canonical_tag = str(int(tag, 10))
                if canonical_tag in {"8", "9", "10"}:
                    raise EmulatorInputError(
                        "protocol driver request fix tags must not include reserved tags 8, 9, or 10"
                    )
                if canonical_tag in canonical_tags:
                    raise EmulatorInputError(
                        f"protocol driver request fix tags contain duplicate tag {canonical_tag}"
                    )
                if not isinstance(value, str) or "\x00" in value or "\x01" in value:
                    raise EmulatorInputError(
                        f"protocol driver request fix tag {canonical_tag} value must be a string without NUL or SOH"
                    )
                try:
                    value_bytes = value.encode("ascii")
                except UnicodeEncodeError as exc:
                    raise EmulatorInputError(
                        f"protocol driver request fix tag {canonical_tag} value must contain ASCII bytes"
                    ) from exc
                if len(value_bytes) > PROTOCOL_REQUEST_MAX_TEXT_BYTES:
                    raise EmulatorInputError(
                        f"protocol driver request fix tag {canonical_tag} value is too long"
                    )
                canonical_tags.add(canonical_tag)
            if "35" not in canonical_tags:
                raise EmulatorInputError(
                    "protocol driver request fix tags must include message type tag 35"
                )
    if "websocket" in request:
        if event != "WS_REQUEST":
            raise EmulatorInputError(
                "protocol driver request websocket is supported only for WS_REQUEST"
            )
        websocket_request = request["websocket"]
        if not isinstance(websocket_request, dict):
            raise EmulatorInputError(
                "protocol driver request websocket must be an object"
            )
        allowed_websocket_fields = {
            "method", "uri", "host", "headers", "sec_websocket_key"
        }
        unknown_websocket_fields = sorted(
            set(websocket_request) - allowed_websocket_fields
        )
        if unknown_websocket_fields:
            raise EmulatorInputError(
                "protocol driver request websocket unsupported field(s): "
                + ", ".join(unknown_websocket_fields)
            )
        for field, default in (
            ("method", "GET"),
            ("uri", "/socket"),
            ("host", "example.test"),
            ("sec_websocket_key", "dGhlIHNhbXBsZSBub25jZQ=="),
        ):
            value = websocket_request.get(field, default)
            if not isinstance(value, str) or not value:
                raise EmulatorInputError(
                    f"protocol driver request websocket {field} must be a non-empty string"
                )
            if "\x00" in value or "\r" in value or "\n" in value:
                raise EmulatorInputError(
                    f"protocol driver request websocket {field} must not contain NUL or line breaks"
                )
            try:
                value_bytes = value.encode("utf-8")
            except UnicodeEncodeError as exc:
                raise EmulatorInputError(
                    f"protocol driver request websocket {field} must be valid UTF-8"
                ) from exc
            if len(value_bytes) > PROTOCOL_REQUEST_MAX_TEXT_BYTES:
                raise EmulatorInputError(
                    f"protocol driver request websocket {field} is too long"
                )
        if websocket_request.get("method", "GET") != "GET":
            raise EmulatorInputError(
                "protocol driver request websocket method must be GET"
            )
        if not websocket_request.get("uri", "/socket").startswith("/"):
            raise EmulatorInputError(
                "protocol driver request websocket uri must be an absolute path"
            )
        try:
            websocket_key = base64.b64decode(
                websocket_request.get(
                    "sec_websocket_key", "dGhlIHNhbXBsZSBub25jZQ=="
                ),
                validate=True,
            )
        except (binascii.Error, ValueError) as exc:
            raise EmulatorInputError(
                "protocol driver request websocket sec_websocket_key must be valid base64"
            ) from exc
        if len(websocket_key) != 16:
            raise EmulatorInputError(
                "protocol driver request websocket sec_websocket_key must decode to 16 bytes"
            )
        websocket_headers = websocket_request.get("headers", {})
        if not isinstance(websocket_headers, dict):
            raise EmulatorInputError(
                "protocol driver request websocket headers must be an object"
            )
        for header_name, header_value in websocket_headers.items():
            if (
                not isinstance(header_name, str)
                or not header_name
                or not isinstance(header_value, str)
                or not header_value
                or "\x00" in header_name
                or "\x00" in header_value
                or "\r" in header_name
                or "\n" in header_name
                or "\r" in header_value
                or "\n" in header_value
            ):
                raise EmulatorInputError(
                    "protocol driver request websocket headers must be non-empty strings without line breaks"
                )
        if {"payload", "payload_base64"} & set(request):
            raise EmulatorInputError(
                "WS_REQUEST protocol driver requests do not accept payload fields"
            )
    if event in {"ICAP_REQUEST", "ICAP_RESPONSE"}:
        icap = request.get("icap")
        if not isinstance(icap, dict):
            raise EmulatorInputError(
                f"{event} protocol driver requests require icap"
            )
        allowed_icap_fields = {
            "message_hex", "message_base64", "method", "uri", "version", "status",
            "phrase", "headers", "encapsulated",
        }
        unknown_icap = sorted(set(icap) - allowed_icap_fields)
        if unknown_icap:
            raise EmulatorInputError(
                "protocol driver request ICAP unsupported field(s): "
                + ", ".join(unknown_icap)
            )
        raw_fields = {"message_hex", "message_base64"}.intersection(icap)
        if len(raw_fields) > 1:
            raise EmulatorInputError(
                "protocol driver request ICAP message_hex and message_base64 are mutually exclusive"
            )
        if raw_fields:
            if set(icap) != raw_fields:
                raise EmulatorInputError(
                    "protocol driver request ICAP raw message cannot be combined with structured fields"
                )
            raw_value = icap[next(iter(raw_fields))]
            if not isinstance(raw_value, str) or not raw_value:
                raise EmulatorInputError(
                    "protocol driver request ICAP raw message must be a non-empty string"
                )
        else:
            version = icap.get("version", "ICAP/1.0")
            if version != "ICAP/1.0":
                raise EmulatorInputError(
                    "protocol driver request ICAP version must be ICAP/1.0"
                )
            if event == "ICAP_REQUEST":
                method = icap.get("method", "REQMOD")
                uri = icap.get("uri", "icap://example.test/reqmod")
                if (
                    not isinstance(method, str)
                    or method.upper() not in {"REQMOD", "RESPMOD", "OPTIONS"}
                ):
                    raise EmulatorInputError(
                        "protocol driver request ICAP method must be REQMOD, RESPMOD, or OPTIONS"
                    )
                if (
                    not isinstance(uri, str)
                    or not uri
                    or not uri.isascii()
                    or any(character.isspace() for character in uri)
                ):
                    raise EmulatorInputError(
                        "protocol driver request ICAP uri must be an ASCII value without whitespace"
                    )
            else:
                status = icap.get("status", 200)
                if (
                    isinstance(status, bool)
                    or not isinstance(status, int)
                    or not 100 <= status <= 999
                ):
                    raise EmulatorInputError(
                        "protocol driver request ICAP status must be an integer from 100 to 999"
                    )
            headers = icap.get("headers", {})
            if not isinstance(headers, dict) or len(headers) > 128:
                raise EmulatorInputError(
                    "protocol driver request ICAP headers must be an object with at most 128 items"
                )
            header_names: set[str] = set()
            for name, value in headers.items():
                if (
                    not isinstance(name, str)
                    or not name
                    or not name.isascii()
                    or not re.fullmatch(r"[!#$%&'*+.^_`|~0-9A-Za-z-]+", name)
                    or not isinstance(value, str)
                    or "\x00" in value
                    or "\r" in value
                    or "\n" in value
                ):
                    raise EmulatorInputError(
                        "protocol driver request ICAP headers must use valid names and values"
                    )
                lowered = name.lower()
                if lowered in header_names:
                    raise EmulatorInputError(
                        f"protocol driver request ICAP header {name!r} is repeated"
                    )
                header_names.add(lowered)
            encapsulated = icap.get("encapsulated")
            if encapsulated is not None and not isinstance(encapsulated, dict):
                raise EmulatorInputError(
                    "protocol driver request ICAP encapsulated must be an object"
                )
        return dict(request)
    if event in {"TDS_REQUEST", "TDS_RESPONSE"}:
        tds = request.get("tds")
        if not isinstance(tds, dict):
            raise EmulatorInputError(
                f"{event} protocol driver requests require tds"
            )
        allowed_tds_fields = {
            "message_hex", "message_base64", "type", "status", "sqltext", "payload_base64"
        }
        unknown_tds = sorted(set(tds) - allowed_tds_fields)
        if unknown_tds:
            raise EmulatorInputError(
                "protocol driver request TDS unsupported field(s): "
                + ", ".join(unknown_tds)
            )
        raw_fields = {"message_hex", "message_base64"}.intersection(tds)
        if len(raw_fields) > 1:
            raise EmulatorInputError(
                "protocol driver request TDS message_hex and message_base64 are mutually exclusive"
            )
        if raw_fields and set(tds) != raw_fields:
            raise EmulatorInputError(
                "protocol driver request TDS raw message cannot be combined with structured fields"
            )
        if not raw_fields:
            packet_type = tds.get("type", 1 if event == "TDS_REQUEST" else 4)
            if (
                isinstance(packet_type, bool)
                or not isinstance(packet_type, int)
                or packet_type not in TDS_PACKET_TYPES
            ):
                raise EmulatorInputError(
                    "protocol driver request TDS type is unsupported"
                )
            sqltext = tds.get("sqltext", "" if event == "TDS_RESPONSE" else "select 1")
            if not isinstance(sqltext, str):
                raise EmulatorInputError(
                    "protocol driver request TDS sqltext must be a string"
                )
            if "payload_base64" in tds and "sqltext" in tds:
                raise EmulatorInputError(
                    "protocol driver request TDS sqltext and payload_base64 are mutually exclusive"
                )
        return dict(request)
    if event.startswith("RTSP_"):
        if event not in {"RTSP_REQUEST", "RTSP_REQUEST_DATA"}:
            raise EmulatorInputError(
                "protocol driver request RTSP supports RTSP_REQUEST and RTSP_REQUEST_DATA only"
            )
        if "message" in request:
            if set(request) & {
                "method", "uri", "version", "headers", "body", "payload", "payload_base64"
            }:
                raise EmulatorInputError(
                    "RTSP message cannot be combined with structured request fields"
                )
        else:
            for field, default in (
                ("method", "DESCRIBE"),
                ("uri", "rtsp://example.test/live"),
                ("version", "RTSP/1.0"),
            ):
                value = request.get(field, default)
                if not isinstance(value, str) or not value:
                    raise EmulatorInputError(
                        f"protocol driver request RTSP {field} must be a non-empty string"
                    )
                if "\x00" in value or "\r" in value or "\n" in value:
                    raise EmulatorInputError(
                        f"protocol driver request RTSP {field} must not contain NUL or line breaks"
                    )
            headers = request.get("headers", {})
            if not isinstance(headers, dict) or len(headers) > 128:
                raise EmulatorInputError(
                    "protocol driver request RTSP headers must be an object with at most 128 items"
                )
            header_names: set[str] = set()
            for name, value in headers.items():
                if (
                    not isinstance(name, str)
                    or not name.isascii()
                    or not name
                    or any(
                        character not in "!#$%&'*+-.^_`|~" and not character.isalnum()
                        for character in name
                    )
                    or not isinstance(value, str)
                    or "\x00" in value
                    or "\r" in value
                    or "\n" in value
                ):
                    raise EmulatorInputError(
                        "protocol driver request RTSP headers must use valid names and values"
                    )
                lowered = name.lower()
                if lowered in header_names:
                    raise EmulatorInputError(
                        f"protocol driver request RTSP header {name!r} is repeated"
                    )
                header_names.add(lowered)
        if "body" in request and ({"payload", "payload_base64"} & set(request)):
            raise EmulatorInputError(
                "RTSP request must use exactly one of body, payload, or payload_base64"
            )
    if event == "PCP_REQUEST":
        if "pcp" not in request:
            raise EmulatorInputError("PCP protocol driver requests require pcp")
        if {"payload", "payload_base64"} & set(request):
            raise EmulatorInputError(
                "PCP protocol driver requests do not accept payload or payload_base64"
            )
    if event in {"RADIUS_AAA_AUTH_REQUEST", "RADIUS_AAA_ACCT_REQUEST"}:
        if "radius" not in request:
            raise EmulatorInputError("RADIUS protocol driver requests require radius")
        if {"payload", "payload_base64"} & set(request):
            raise EmulatorInputError(
                "RADIUS protocol driver requests do not accept payload or payload_base64"
            )
    if event == "WS_REQUEST" and "websocket" not in request:
        raise EmulatorInputError("WS_REQUEST protocol driver requests require websocket")

    headers = request.get("headers")
    if headers is not None:
        if not isinstance(headers, dict):
            raise EmulatorInputError("protocol driver request headers must be an object")
        for key, value in headers.items():
            if not isinstance(key, str) or not isinstance(value, str):
                raise EmulatorInputError(
                    "protocol driver request headers must contain string keys and values"
                )
            for field, text in (("header name", key), ("header value", value)):
                if "\r" in text or "\n" in text:
                    raise EmulatorInputError(
                        f"protocol driver request {field} must not contain line breaks"
                    )
                if "\x00" in text:
                    raise EmulatorInputError(
                        f"protocol driver request {field} must not contain NUL"
                    )
                try:
                    text_bytes = text.encode("utf-8")
                except UnicodeEncodeError as exc:
                    raise EmulatorInputError(
                        f"protocol driver request {field} must be valid UTF-8"
                    ) from exc
                if len(text_bytes) > PROTOCOL_REQUEST_MAX_TEXT_BYTES:
                    raise EmulatorInputError(
                        f"protocol driver request {field} exceeds the "
                        f"{PROTOCOL_REQUEST_MAX_TEXT_BYTES // 1024} KiB limit"
                    )

    timeout = request.get("timeout")
    if timeout is not None:
        if isinstance(timeout, bool) or not isinstance(timeout, (int, float)):
            raise EmulatorInputError("protocol driver request timeout must be a number")
        try:
            timeout_value = float(timeout)
        except (OverflowError, ValueError) as exc:
            raise EmulatorInputError(
                "protocol driver request timeout must be a finite number"
            ) from exc
        if not math.isfinite(timeout_value) or not 0 < timeout_value <= 60:
            raise EmulatorInputError(
                "protocol driver request timeout must be greater than 0 and at most 60"
            )
    for field, minimum, maximum in (
        ("qclass", 1, 65535),
        ("transaction_id", 0, 65535),
        ("keepalive", 0, 65535),
    ):
        value = request.get(field)
        if value is not None and (
            isinstance(value, bool) or not isinstance(value, int) or not minimum <= value <= maximum
        ):
            raise EmulatorInputError(
                f"protocol driver request {field} must be between {minimum} and {maximum}"
            )
    recursion_desired = request.get("recursion_desired")
    if recursion_desired is not None and not isinstance(recursion_desired, bool):
        raise EmulatorInputError(
            "protocol driver request recursion_desired must be a boolean"
        )
    qtype = request.get("qtype")
    if qtype is not None and (
        isinstance(qtype, bool)
        or not isinstance(qtype, (str, int))
        or (isinstance(qtype, int) and not 1 <= qtype <= 65535)
    ):
        raise EmulatorInputError(
            "protocol driver request qtype must be a string or a value from 1 to 65535"
        )

    if event.startswith("DNS_") and "qname" not in request:
        raise EmulatorInputError("DNS protocol driver requests require qname")
    if event.startswith("MQTT_") and "topic" not in request:
        raise EmulatorInputError("MQTT protocol driver requests require topic")
    if (
        not event.startswith(("DNS_", "MQTT_", "SIP_", "RTSP_", "ICAP_", "TDS_"))
        and event not in {
            "PCP_REQUEST", "RADIUS_AAA_AUTH_REQUEST", "RADIUS_AAA_ACCT_REQUEST",
            "WS_REQUEST", "FIX_HEADER", "FIX_MESSAGE",
        }
        and "fix" not in request
        and not {"payload", "payload_base64"} & set(request)
    ):
        raise EmulatorInputError(
            "raw protocol driver requests require payload or payload_base64"
        )
    return dict(request)


def _protocol_request_packet(event: str, request: dict[str, Any]) -> dict[str, Any]:
    """Convert a protocol-driver fixture into one normalized emulator packet."""
    common = {
        "direction": "client_to_server",
        "source": {"address": "192.0.2.10", "port": 53000},
        "destination": {"address": "192.0.2.53", "port": 53},
    }
    if event.startswith("DNS_"):
        packet = {
            **common,
            "protocol": "dns",
            "qname": request["qname"],
            "qtype": str(request.get("qtype", "A")),
            "qclass": str(request.get("qclass", "IN")),
            "rd": request.get("recursion_desired", True),
            "id": request.get("transaction_id", 0x1705),
        }
    elif event.startswith("MQTT_"):
        packet = {
            **common,
            "protocol": "mqtt",
            "destination": {"address": "192.0.2.53", "port": 1883},
            "type": "PUBLISH",
            "client_id": request.get("client_id", "testcl-1705"),
            "topic": request["topic"],
            "keep_alive": request.get("keepalive", 30),
        }
        if "payload_base64" in request:
            try:
                packet["payload_hex"] = base64.b64decode(
                    request["payload_base64"], validate=True
                ).hex()
            except (binascii.Error, ValueError) as exc:
                raise EmulatorInputError(
                    "protocol driver request payload_base64 is not valid base64"
                ) from exc
        else:
            packet["payload"] = request.get("payload", "testcl")
    elif event.startswith("SIP_"):
        packet = {
            **common,
            "protocol": "sip",
            "destination": {"address": "192.0.2.53", "port": 5060},
            "transport": "udp",
            "type": "response" if event.endswith("RESPONSE") else "request",
        }
        if "message" in request:
            packet["message"] = (
                request["message"].replace("\r\n", "\n").replace("\r", "\n")
                .replace("\n", "\r\n")
            )
        else:
            packet.update(
                {
                    "method": request.get("method", "OPTIONS"),
                    "uri": request.get("uri", "sip:test@example.invalid"),
                    "headers": request.get("headers", {}),
                    "body": request.get("body", ""),
                }
            )
            if packet["type"] == "response":
                status = str(request.get("status", "200 OK"))
                status_parts = status.split(None, 1)
                try:
                    packet["status"] = int(status_parts[0])
                except (TypeError, ValueError) as exc:
                    raise EmulatorInputError(
                        "protocol driver request SIP status must begin with an integer"
                    ) from exc
                packet["phrase"] = status_parts[1] if len(status_parts) == 2 else ""
    elif event == "PCP_REQUEST":
        pcp_request = request.get("pcp")
        if not isinstance(pcp_request, dict):
            raise EmulatorInputError("PCP protocol driver requests require pcp")
        packet = {
            **common,
            "protocol": "pcp",
            "destination": {"address": "192.0.2.53", "port": PCP_PORT},
            "pcp": pcp_request,
        }
    elif event in {"RADIUS_AAA_AUTH_REQUEST", "RADIUS_AAA_ACCT_REQUEST"}:
        radius_request = request.get("radius")
        if not isinstance(radius_request, dict):
            raise EmulatorInputError("RADIUS protocol driver requests require radius")
        expected_code = (
            RADIUS_ACCOUNTING_REQUEST
            if event.endswith("ACCT_REQUEST")
            else RADIUS_AUTH_REQUEST
        )
        radius_code = radius_request.get("code", expected_code)
        if isinstance(radius_code, str):
            radius_code = RADIUS_REQUEST_CODE_NAMES.get(
                radius_code.lower(), radius_code
            )
        if radius_code != expected_code:
            raise EmulatorInputError(
                f"protocol driver request radius code does not match {event}"
            )
        packet = {
            **common,
            "protocol": "radius",
            "destination": {
                "address": "192.0.2.53",
                "port": 1813 if event.endswith("ACCT_REQUEST") else 1812,
            },
            "code": radius_code,
            "id": radius_request.get("id", 0),
            "authenticator_hex": radius_request.get(
                "authenticator_hex", "00" * RADIUS_AUTHENTICATOR_BYTES
            ),
            "avps": radius_request.get("avps", []),
        }
    elif event == "WS_REQUEST":
        websocket_request = request.get("websocket")
        if not isinstance(websocket_request, dict):
            raise EmulatorInputError(
                "WS_REQUEST protocol driver requests require websocket"
            )
        headers = dict(websocket_request.get("headers", {}))
        defaults = {
            "Host": websocket_request.get("host", "example.test"),
            "Upgrade": "websocket",
            "Connection": "Upgrade",
            "Sec-WebSocket-Key": websocket_request.get(
                "sec_websocket_key", "dGhlIHNhbXBsZSBub25jZQ=="
            ),
            "Sec-WebSocket-Version": "13",
        }
        existing = {str(key).lower() for key in headers}
        for key, value in defaults.items():
            if key.lower() not in existing:
                headers[key] = value
        packet = {
            **common,
            "protocol": "websocket",
            "destination": {"address": "192.0.2.53", "port": 80},
            "type": "request",
            "method": websocket_request.get("method", "GET"),
            "uri": websocket_request.get("uri", "/socket"),
            "host": websocket_request.get("host", "example.test"),
            "headers": headers,
        }
    elif event in {"ICAP_REQUEST", "ICAP_RESPONSE"}:
        icap_request = request.get("icap")
        if not isinstance(icap_request, dict):
            raise EmulatorInputError(
                f"{event} protocol driver requests require icap"
            )
        if "message_hex" in icap_request or "message_base64" in icap_request:
            raise EmulatorInputError(
                "local ICAP replay accepts structured fields; use the external driver for raw message bytes"
            )
        direction = (
            "client_to_server" if event == "ICAP_REQUEST" else "server_to_client"
        )
        packet = {
            "protocol": "icap",
            "direction": direction,
            "source": (
                {"address": "192.0.2.10", "port": 53000}
                if event == "ICAP_REQUEST"
                else {"address": "192.0.2.53", "port": 1344}
            ),
            "destination": (
                {"address": "192.0.2.53", "port": 1344}
                if event == "ICAP_REQUEST"
                else {"address": "192.0.2.10", "port": 53000}
            ),
            "type": "request" if event == "ICAP_REQUEST" else "response",
            "method": icap_request.get("method", "REQMOD"),
            "uri": icap_request.get("uri", "icap://example.test/reqmod"),
            "status": icap_request.get("status", 204),
            "headers": icap_request.get("headers", {}),
        }
    elif event in {"TDS_REQUEST", "TDS_RESPONSE"}:
        tds_request = request.get("tds")
        if not isinstance(tds_request, dict):
            raise EmulatorInputError(
                f"{event} protocol driver requests require tds"
            )
        if "message_hex" in tds_request or "message_base64" in tds_request:
            raise EmulatorInputError(
                "local TDS replay accepts structured fields; use the external driver for raw message bytes"
            )
        direction = (
            "client_to_server" if event == "TDS_REQUEST" else "server_to_client"
        )
        packet = {
            "protocol": "tds",
            "direction": direction,
            "source": (
                {"address": "192.0.2.10", "port": 53000}
                if event == "TDS_REQUEST"
                else {"address": "192.0.2.53", "port": 1433}
            ),
            "destination": (
                {"address": "192.0.2.53", "port": 1433}
                if event == "TDS_REQUEST"
                else {"address": "192.0.2.10", "port": 53000}
            ),
            "type": tds_request.get("type", 1 if event == "TDS_REQUEST" else 4),
            "sqltext": tds_request.get("sqltext", "" if event == "TDS_RESPONSE" else "select 1"),
        }
    elif event in {"FIX_HEADER", "FIX_MESSAGE"}:
        fix_request = request.get("fix")
        if not isinstance(fix_request, dict):
            raise EmulatorInputError(
                f"{event} protocol driver requests require fix"
            )
        if "message_hex" in fix_request or "message_base64" in fix_request:
            raise EmulatorInputError(
                "local FIX replay accepts structured tags; use the external driver for raw message bytes"
            )
        tags = fix_request.get("tags")
        if not isinstance(tags, dict):
            raise EmulatorInputError("FIX protocol driver requests require fix.tags")
        packet = {
            **common,
            "protocol": "fix",
            "destination": {"address": "192.0.2.53", "port": 9876},
            "fix": {"tags": tags},
        }
    elif event in {"CLIENT_DATA", "SERVER_DATA"} and "ldap" in request:
        ldap_request = request.get("ldap")
        if not isinstance(ldap_request, dict):
            raise EmulatorInputError("protocol driver request ldap must be an object")
        direction = "client_to_server" if event == "CLIENT_DATA" else "server_to_client"
        packet = {
            **common,
            "protocol": "ldap",
            "direction": direction,
            "source": (
                {"address": "192.0.2.10", "port": 53000}
                if event == "CLIENT_DATA"
                else {"address": "192.0.2.53", "port": 389}
            ),
            "destination": (
                {"address": "192.0.2.53", "port": 389}
                if event == "CLIENT_DATA"
                else {"address": "192.0.2.10", "port": 53000}
            ),
        }
        if "message_hex" in ldap_request:
            packet["payload_hex"] = ldap_request["message_hex"]
        elif "message_base64" in ldap_request:
            try:
                packet["payload_hex"] = base64.b64decode(
                    ldap_request["message_base64"], validate=True
                ).hex()
            except (binascii.Error, ValueError) as exc:
                raise EmulatorInputError(
                    "protocol driver request ldap message_base64 is not valid base64"
                ) from exc
        else:
            operation = str(
                ldap_request.get(
                    "operation",
                    "bindRequest" if event == "CLIENT_DATA" else "bindResponse",
                )
            )
            packet.update(
                {
                    "type": "command" if event == "CLIENT_DATA" else "response",
                    "command": operation,
                    "operation": operation,
                    "message_id": ldap_request.get("message_id", 1),
                    "dn": ldap_request.get("dn", ""),
                    "result_code": ldap_request.get("result_code", 0),
                    "diagnostic": ldap_request.get("diagnostic", ""),
                    "version": ldap_request.get("version", 0),
                    "scope": ldap_request.get("scope", 0),
                }
            )
    elif event.startswith("RTSP_"):
        if event not in {"RTSP_REQUEST", "RTSP_REQUEST_DATA"}:
            raise EmulatorInputError(
                "local protocol replay supports RTSP_REQUEST and RTSP_REQUEST_DATA only"
            )
        if "message" in request:
            raw = request["message"].replace("\r\n", "\n").replace("\r", "\n")
            header_text, separator, body = raw.partition("\n\n")
            lines = header_text.split("\n")
            if not lines or len(lines[0].split()) != 3:
                raise EmulatorInputError(
                    "protocol driver request RTSP message must have a valid request line"
                )
            method, uri, version = lines[0].split()
            headers: dict[str, str] = {}
            for line in lines[1:]:
                if not line:
                    continue
                if ":" not in line:
                    raise EmulatorInputError(
                        "protocol driver request RTSP message has an invalid header"
                    )
                name, value = line.split(":", 1)
                if not name or name.lower() in {key.lower() for key in headers}:
                    raise EmulatorInputError(
                        "protocol driver request RTSP message has duplicate or empty headers"
                    )
                headers[name] = value.strip()
            if not separator:
                body = ""
        else:
            method = request.get("method", "DESCRIBE")
            uri = request.get("uri", "rtsp://example.test/live")
            version = request.get("version", "RTSP/1.0")
            headers = request.get("headers", {})
            body = request.get("body", request.get("payload", ""))
            if "payload_base64" in request:
                try:
                    body = base64.b64decode(request["payload_base64"], validate=True).decode(
                        "utf-8"
                    )
                except (binascii.Error, UnicodeDecodeError, ValueError) as exc:
                    raise EmulatorInputError(
                        "protocol driver request RTSP payload_base64 must contain UTF-8 bytes"
                    ) from exc
        packet = {
            **common,
            "protocol": "rtsp",
            "destination": {"address": "192.0.2.53", "port": 554},
            "type": "request",
            "method": method,
            "uri": uri,
            "version": version,
            "headers": headers,
            "body": body,
        }
    else:
        raise EmulatorInputError(
        "local protocol replay currently supports HTTP, DNS, MQTT, SIP, RTSP, ICAP, PCP, RADIUS, LDAP, FIX, and WebSocket requests"
        )
    try:
        return _normalise_packets([packet])[0]
    except (KeyError, TypeError, ValueError) as exc:  # pragma: no cover - boundary guard
        raise EmulatorInputError(f"could not build local {event} protocol packet: {exc}") from exc


def _normalise_command_probe_request(
    root: Path,
    request: Any,
    *,
    allow_external_protocol_request: bool = False,
    prepare_external_protocol_request: bool = False,
) -> dict[str, Any]:
    """Validate a command probe and construct its fixture-only scenario."""
    if not isinstance(request, dict):
        raise EmulatorInputError("command probe request must be a JSON object")
    allowed = {
        "command",
        "args",
        "event",
        "profiles",
        "state",
        "request",
        "scenario",
    }
    unknown = sorted(set(request) - allowed)
    if unknown:
        raise EmulatorInputError(
            f"unsupported command probe field(s): {', '.join(unknown)}"
        )

    command = request.get("command")
    catalog = _command_probe_catalog_entry(root, command)
    if "args" in request and request["args"] is None:
        raise EmulatorInputError("command probe args must be an array when provided")
    args = _normalise_command_probe_args(request.get("args"))

    event = request.get("event")
    event_name = _require_string(event, "command probe event")
    if not re.fullmatch(r"[A-Z][A-Z0-9_]*", event_name):
        raise EmulatorInputError(
            "command probe event must be an uppercase iRule event name"
        )
    event_profiles = _load_event_profiles(root)
    if event_name not in event_profiles:
        event_status = _target_status(
            event_name,
            TMOS_17_5_POST_TARGET_EVENTS,
            TMOS_17_5_UNAVAILABLE_EVENTS,
        )
        if event_status != "available-in-tmos-17.5":
            raise EmulatorInputError(
                f"event is {event_status}: {event_name}"
            )
        raise EmulatorInputError(f"unknown iRule event: {event_name}")

    _load_session_class(root)
    try:
        from compiler.registry import REGISTRY
        from compiler.registry.namespace_data import event_satisfies, get_event_props
        from compiler.registry.namespace_models import EventProps
    except ImportError as exc:  # pragma: no cover - depends on external checkout
        raise EmulatorInputError(f"could not load tcl-lsp event metadata: {exc}") from exc
    command_spec = _f5_catalog_spec(REGISTRY, command)
    event_props = get_event_props(event_name)
    if event_props is None and event_name in TMOS_17_5_EVENT_OVERRIDES:
        override = TMOS_17_5_EVENT_OVERRIDES[event_name]
        event_props = EventProps(
            client_side=override["client_side"],
            server_side=override["server_side"],
            transport=override["transport"],
            implied_profiles=override["implied_profiles"],
            flow=override["flow"],
            deprecated=override["deprecated"],
            common=override["common"],
        )
    requirements = command_spec.event_requires if command_spec is not None else None
    if requirements is not None and event_props is not None and not event_satisfies(
        event_props, requirements, event_name
    ):
        raise EmulatorInputError(
            f"command {command} is not valid in catalogued event {event_name}"
        )

    base_scenario = request.get("scenario", {})
    if not isinstance(base_scenario, dict):
        raise EmulatorInputError("command probe scenario must be a JSON object")
    forbidden = sorted(
        set(base_scenario)
        & {"irule", "irule_file", "irules", "request", "requests", "packets"}
    )
    if forbidden:
        raise EmulatorInputError(
            "command probe scenario cannot provide " + ", ".join(forbidden)
        )
    scenario = dict(base_scenario)

    profiles = request.get("profiles", scenario.get("profiles", DEFAULT_PROFILES))
    if not isinstance(profiles, list) or not profiles or len(profiles) > 64:
        raise EmulatorInputError(
            "command probe profiles must be a non-empty array of at most 64 strings"
        )
    if not all(isinstance(profile, str) and profile for profile in profiles):
        raise EmulatorInputError("command probe profiles must be strings")
    if any("\x00" in profile or len(profile.encode("utf-8")) > 256 for profile in profiles):
        raise EmulatorInputError(
            "command probe profiles must not contain NUL and must be at most 256 UTF-8 bytes"
        )

    state = request.get("state")
    http_request = request.get("request")
    protocol_packet: dict[str, Any] | None = None
    if "state" in request and state is None:
        raise EmulatorInputError("command probe state must be an object when provided")
    if "request" in request and http_request is None:
        raise EmulatorInputError("command probe request must be an object when provided")
    if "state" in request and "request" in request:
        raise EmulatorInputError("command probe accepts state or request, not both")
    if http_request is not None:
        if event_name not in {"HTTP_REQUEST", "HTTP_RESPONSE"}:
            if not allow_external_protocol_request:
                raise EmulatorInputError(
                    "command probe request input is supported only for HTTP_REQUEST or HTTP_RESPONSE unless an external protocol allowance is enabled"
                )
            http_request = _normalise_protocol_request(event_name, http_request)
            if prepare_external_protocol_request:
                protocol_packet = _protocol_request_packet(event_name, http_request)
            http_request = None
        else:
            if not isinstance(http_request, dict):
                raise EmulatorInputError("command probe request must be a JSON object")
            http_request = _normalise_requests({"request": http_request})[0]
    _normalise_event(event_name, state)
    scenario["profiles"] = list(profiles)
    scenario["irule"] = _command_probe_irule(event_name, command, args)
    return {
        "command": command,
        "args": args,
        "event": event_name,
        "profiles": list(profiles),
        "state": state,
        "request": http_request,
        "packet": protocol_packet,
        "scenario": scenario,
        "catalog": catalog,
    }


def _build_conformance(root: Path) -> dict[str, Any]:
    """Report static catalog coverage without pretending stubs are semantics."""
    registry, status_map = _runtime_status_map(root)
    try:
        from compiler.registry.namespace_registry import NAMESPACE_REGISTRY
    except ImportError as exc:  # pragma: no cover - depends on external checkout
        raise EmulatorInputError(f"could not load tcl-lsp event registry: {exc}") from exc

    command_counts = {
        "handwritten-mock": 0,
        "semantic-mock": 0,
        "generated-stub": 0,
        "no-runtime-handler": 0,
    }
    catalog_kind_counts = {
        "f5-irule": 0,
        "tcllib": 0,
        "tcl-core": 0,
        "irule-language": 0,
    }
    target_kind_status_counts = {
        "f5-irule": {status: 0 for status in sorted(RUNTIME_STATUS_VALUES)},
        "tcllib": {status: 0 for status in sorted(RUNTIME_STATUS_VALUES)},
        "tcl-core": {status: 0 for status in sorted(RUNTIME_STATUS_VALUES)},
        "irule-language": {status: 0 for status in sorted(RUNTIME_STATUS_VALUES)},
    }
    for name, status in status_map.items():
        command_counts[status] = command_counts.get(status, 0) + 1
        kind = _catalog_kind(name, _f5_catalog_spec(registry, name))
        catalog_kind_counts[kind] += 1
        if (
            name not in TMOS_17_5_POST_TARGET_COMMANDS
            and name not in TMOS_17_5_UNAVAILABLE_COMMANDS
        ):
            target_kind_status_counts[kind][status] += 1
    event_names = _catalog_event_names(NAMESPACE_REGISTRY)
    post_target_commands = sorted(
        name for name in status_map if name in TMOS_17_5_POST_TARGET_COMMANDS
    )
    unavailable_commands = sorted(
        name for name in status_map if name in TMOS_17_5_UNAVAILABLE_COMMANDS
    )
    post_target_events = sorted(
        name for name in event_names if name in TMOS_17_5_POST_TARGET_EVENTS
    )
    unavailable_events = sorted(
        name for name in event_names if name in TMOS_17_5_UNAVAILABLE_EVENTS
    )
    supported_events = [
        name
        for name in event_names
        if (
            name in PACKET_EVENT_ADAPTERS
            and name not in TMOS_17_5_POST_TARGET_EVENTS
            and name not in TMOS_17_5_UNAVAILABLE_EVENTS
        )
    ]
    implementation_buckets: dict[tuple[str, str], list[str]] = {}
    implementation_statuses = {"generated-stub", "no-runtime-handler"}
    for name, status in status_map.items():
        if (
            name in TMOS_17_5_POST_TARGET_COMMANDS
            or name in TMOS_17_5_UNAVAILABLE_COMMANDS
            or status not in implementation_statuses
        ):
            continue
        spec = _f5_catalog_spec(registry, name)
        namespace = name.split("::", 1)[0] if "::" in name else ""
        if _catalog_kind(name, spec) == "f5-irule":
            implementation_buckets.setdefault((namespace, status), []).append(name)
    implementation_queue = [
        {
            "namespace": namespace,
            "runtime_status": status,
            "count": len(names),
        }
        for (namespace, status), names in sorted(implementation_buckets.items())
    ]
    target_command_names = [
        name
        for name in status_map
        if name not in TMOS_17_5_POST_TARGET_COMMANDS
        and name not in TMOS_17_5_UNAVAILABLE_COMMANDS
    ]
    target_runtime_counts = {
        status: sum(status_map[name] == status for name in target_command_names)
        for status in sorted(RUNTIME_STATUS_VALUES)
    }
    target_f5_runtime_counts = target_kind_status_counts["f5-irule"]
    target_support_runtime_counts = {
        status: sum(
            target_kind_status_counts[kind][status]
            for kind in ("tcllib", "tcl-core")
        )
        for status in sorted(RUNTIME_STATUS_VALUES)
    }
    target_unmapped_events = [
        name
        for name in event_names
        if name not in PACKET_EVENT_ADAPTERS
        and name not in TMOS_17_5_POST_TARGET_EVENTS
        and name not in TMOS_17_5_UNAVAILABLE_EVENTS
    ]
    behavioral_command_count = sum(
        target_runtime_counts[status]
        for status in ("handwritten-mock", "semantic-mock")
    )
    return {
        "status": "ok",
        "schema_version": 1,
        "profile": "tmos-17.5",
        "tmos_version": TMOS_VERSION,
        "source": {
            "name": "tcl-lsp f5-irules registry",
            "commit": os.environ.get("TCL_LSP_COMMIT", "unknown"),
            "event_overrides": sorted(TMOS_17_5_EVENT_OVERRIDES),
            "unavailable_commands": sorted(TMOS_17_5_UNAVAILABLE_COMMANDS),
            "unavailable_events": sorted(TMOS_17_5_UNAVAILABLE_EVENTS),
        },
        "commands": {
            "catalog_count": len(status_map),
            "target_catalog_count": (
                len(status_map) - len(post_target_commands) - len(unavailable_commands)
            ),
            "post_target_count": len(post_target_commands),
            "post_target_commands": post_target_commands,
            "unavailable_count": len(unavailable_commands),
            "unavailable_commands": unavailable_commands,
            "runtime_status_counts": command_counts,
            "catalog_kind_counts": catalog_kind_counts,
            "target_catalog_kind_runtime_status_counts": target_kind_status_counts,
            "target_f5_command_count": sum(target_kind_status_counts["f5-irule"].values()),
            "implementation_queue": {
                "candidate_statuses": sorted(implementation_statuses),
                "command_count": sum(item["count"] for item in implementation_queue),
                "buckets": implementation_queue,
            },
            "runtime_status_meaning": {
                "handwritten-mock": "implemented behavioral mock in the loaded Tcl framework",
                "semantic-mock": "implemented behavioral mock in the TesTcl adapter overlay",
                "generated-stub": "recognized command with generated placeholder behavior",
                "no-runtime-handler": "catalogued command without a matching runtime proc",
            },
        },
        "events": {
            "catalog_count": len(event_names),
            "target_catalog_count": len(event_names) - len(post_target_events) - len(unavailable_events),
            "post_target_count": len(post_target_events),
            "post_target_events": post_target_events,
            "unavailable_count": len(unavailable_events),
            "unavailable_events": unavailable_events,
            "packet_adapter_count": len(supported_events),
            "packet_adapter_events": [
                {"name": name, "adapter": PACKET_EVENT_ADAPTERS[name]}
                for name in supported_events
            ],
            "unmapped_events": [name for name in event_names if name not in PACKET_EVENT_ADAPTERS],
        },
        "coverage": {
            "command_catalog": {
                "status": "complete",
                "catalog_count": len(status_map),
                "target_count": len(target_command_names),
            },
            "command_behavior": {
                "status": "partial",
                "target_runtime_status_counts": target_runtime_counts,
                "behavioral_count": behavioral_command_count,
                "placeholder_count": target_runtime_counts["generated-stub"],
                "unhandled_count": target_runtime_counts["no-runtime-handler"],
            },
            "f5_command_behavior": {
                "status": "partial",
                "target_runtime_status_counts": dict(target_f5_runtime_counts),
                "behavioral_count": sum(
                    target_f5_runtime_counts[status]
                    for status in ("handwritten-mock", "semantic-mock")
                ),
                "placeholder_count": target_f5_runtime_counts["generated-stub"],
                "unhandled_count": target_f5_runtime_counts["no-runtime-handler"],
            },
            "support_command_behavior": {
                "status": "partial",
                "target_runtime_status_counts": target_support_runtime_counts,
                "behavioral_count": sum(
                    target_support_runtime_counts[status]
                    for status in ("handwritten-mock", "semantic-mock")
                ),
                "placeholder_count": target_support_runtime_counts["generated-stub"],
                "unhandled_count": target_support_runtime_counts["no-runtime-handler"],
            },
            "event_catalog": {
                "status": "complete",
                "catalog_count": len(event_names),
                "target_count": len(event_names)
                - len(post_target_events)
                - len(unavailable_events),
            },
            "event_lifecycle": {
                "status": "partial",
                "target_adapter_count": len(supported_events),
                "target_unmapped_count": len(target_unmapped_events),
                "target_unmapped_events": target_unmapped_events,
            },
        },
        "interpretation": (
            "This is static catalog-to-runtime coverage. It is not a claim that "
            "generated stubs reproduce BIG-IP TMM semantics."
        ),
    }


def _build_behavior_coverage(root: Path, packs: Any) -> dict[str, Any]:
    """Map behavior-pack usage onto the available TMOS 17.5 F5 catalog."""
    if not isinstance(packs, list) or not packs:
        raise EmulatorInputError("behavior coverage packs must be a non-empty array")
    if len(packs) > BEHAVIOR_COVERAGE_MAX_PACKS:
        raise EmulatorInputError(
            f"behavior coverage accepts at most {BEHAVIOR_COVERAGE_MAX_PACKS} packs"
        )
    try:
        encoded = json.dumps(
            packs, ensure_ascii=False, allow_nan=False, separators=(",", ":")
        ).encode("utf-8")
    except (TypeError, ValueError, OverflowError) as exc:
        raise EmulatorInputError(
            "behavior coverage packs must contain only JSON-compatible values"
        ) from exc
    if len(encoded) > BEHAVIOR_COVERAGE_MAX_BYTES:
        raise EmulatorInputError(
            f"behavior coverage packs exceed the {BEHAVIOR_COVERAGE_MAX_BYTES // (1024 * 1024)} MiB limit"
        )

    registry, status_map = _runtime_status_map(root)
    target_names = sorted(
        name
        for name in status_map
        if _catalog_kind(name, _f5_catalog_spec(registry, name)) == "f5-irule"
        if _target_status(
            name,
            TMOS_17_5_POST_TARGET_COMMANDS,
            TMOS_17_5_UNAVAILABLE_COMMANDS,
        )
        == "available-in-tmos-17.5"
    )
    target_name_set = set(target_names)
    tcl_dir = root / "tooling" / "irule_test" / "tcl"
    handwritten = _proc_names(tcl_dir / "command_mocks.tcl")
    generated = _proc_names(tcl_dir / "_mock_stubs.tcl")
    usage: dict[str, dict[str, Any]] = {}
    pack_rows: list[dict[str, Any]] = []
    seen_pack_names: set[str] = set()

    def record_usage(
        name: str,
        pack_name: str,
        case_id: str,
        source_kind: str,
        occurrences: int = 1,
        events: Any = None,
    ) -> None:
        if not isinstance(name, str) or not name:
            return
        entry = usage.setdefault(
            name,
            {
                "occurrences": 0,
                "packs": set(),
                "cases": set(),
                "events": set(),
                "source_kinds": set(),
            },
        )
        occurrence_count = (
            occurrences
            if isinstance(occurrences, int) and not isinstance(occurrences, bool)
            else 1
        )
        entry["occurrences"] += max(1, occurrence_count)
        entry["packs"].add(pack_name)
        entry["cases"].add(case_id)
        entry["source_kinds"].add(source_kind)
        if isinstance(events, list):
            entry["events"].update(event for event in events if isinstance(event, str))

    for pack in packs:
        prepared = _normalise_behavior_pack(root, pack)
        pack_name = prepared["name"]
        if pack_name in seen_pack_names:
            raise EmulatorInputError(
                f"behavior coverage contains duplicate pack name {pack_name!r}"
            )
        seen_pack_names.add(pack_name)
        pack_commands: set[str] = set()
        probe_case_count = 0
        scenario_case_count = 0
        analysis_unavailable_count = 0
        analysis_warnings: list[str] = []
        for case in prepared["cases"]:
            case_id = case["id"]
            if case["kind"] == "probe":
                probe_case_count += 1
                command = case["probe"].get("command")
                if isinstance(command, str) and command:
                    record_usage(
                        command, pack_name, case_id, "probe", events=[case["probe"].get("event", "")]
                    )
                    pack_commands.add(command)
                continue

            scenario_case_count += 1
            scenario = case["scenario"]
            profiles = scenario.get("profiles", DEFAULT_PROFILES)
            analysis = _analyze_rule_capabilities(
                root, scenario.get("irule", ""), profiles
            )
            if analysis.get("analysis") == "unavailable":
                analysis_unavailable_count += 1
            for warning in analysis.get("warnings", []):
                if isinstance(warning, dict) and isinstance(warning.get("message"), str):
                    analysis_warnings.append(warning["message"])
            for command_row in analysis.get("commands", []):
                if not isinstance(command_row, dict):
                    continue
                command = command_row.get("name")
                if not isinstance(command, str) or not command:
                    continue
                record_usage(
                    command,
                    pack_name,
                    case_id,
                    "scenario",
                    occurrences=command_row.get("occurrences", 1),
                    events=command_row.get("events"),
                )
                pack_commands.add(command)
        pack_rows.append(
            {
                "name": pack_name,
                "case_count": len(prepared["cases"]),
                "probe_case_count": probe_case_count,
                "scenario_case_count": scenario_case_count,
                "command_count": len(pack_commands),
                "commands": sorted(pack_commands),
                "analysis_unavailable_count": analysis_unavailable_count,
                "analysis_warnings": sorted(set(analysis_warnings)),
            }
        )

    def usage_row(name: str) -> dict[str, Any]:
        entry = usage.get(name)
        if entry is None:
            return {
                "covered": False,
                "occurrences": 0,
                "pack_count": 0,
                "packs": [],
                "case_count": 0,
                "cases": [],
                "events": [],
                "source_kinds": [],
            }
        return {
            "covered": True,
            "occurrences": entry["occurrences"],
            "pack_count": len(entry["packs"]),
            "packs": sorted(entry["packs"]),
            "case_count": len(entry["cases"]),
            "cases": sorted(entry["cases"]),
            "events": sorted(entry["events"]),
            "source_kinds": sorted(entry["source_kinds"]),
        }

    commands: list[dict[str, Any]] = []
    runtime_status_counts = {status: 0 for status in sorted(RUNTIME_STATUS_VALUES)}
    covered_runtime_status_counts = {status: 0 for status in sorted(RUNTIME_STATUS_VALUES)}
    uncovered_by_namespace: dict[str, int] = {}
    covered_count = 0
    for name in target_names:
        runtime_status = status_map[name]
        runtime_status_counts[runtime_status] += 1
        row = usage_row(name)
        if row["covered"]:
            covered_count += 1
            covered_runtime_status_counts[runtime_status] += 1
            next_action = (
                "deepen-semantic-vector"
                if runtime_status == "semantic-mock"
                else "extend-behavior-vector"
            )
        else:
            namespace = name.split("::", 1)[0] if "::" in name else ""
            uncovered_by_namespace[namespace] = uncovered_by_namespace.get(namespace, 0) + 1
            next_action = "add-behavior-vector"
        commands.append(
            {
                "name": name,
                "namespace": name.split("::", 1)[0] if "::" in name else "",
                "runtime_status": runtime_status,
                "target_status": "available-in-tmos-17.5",
                "next_action": next_action,
                **row,
            }
        )

    out_of_scope_usage: list[dict[str, Any]] = []
    for name in sorted(set(usage) - target_name_set):
        entry = usage[name]
        spec = _f5_catalog_spec(registry, name) or registry.get_any(name)
        out_of_scope_usage.append(
            {
                "name": name,
                "catalog_kind": _catalog_kind(name, spec) if spec is not None else "unknown",
                "runtime_status": (
                    _capability_status(
                        _mock_proc_name(name),
                        handwritten,
                        generated,
                    )
                    if spec is not None
                    else "unknown-command"
                ),
                "occurrences": entry["occurrences"],
                "packs": sorted(entry["packs"]),
                "cases": sorted(entry["cases"]),
                "events": sorted(entry["events"]),
            }
        )

    total_cases = sum(pack["case_count"] for pack in pack_rows)
    probe_cases = sum(pack["probe_case_count"] for pack in pack_rows)
    scenario_cases = sum(pack["scenario_case_count"] for pack in pack_rows)
    uncovered_count = len(target_names) - covered_count
    return {
        "status": "ok",
        "schema_version": 1,
        "profile": "tmos-17.5",
        "tmos_version": TMOS_VERSION,
        "source": "behavior-packs",
        "summary": {
            "behavior_pack_count": len(pack_rows),
            "case_count": total_cases,
            "probe_case_count": probe_cases,
            "scenario_case_count": scenario_cases,
            "target_f5_command_count": len(target_names),
            "covered_command_count": covered_count,
            "uncovered_command_count": uncovered_count,
            "coverage_percent": round(covered_count * 100 / len(target_names), 2)
            if target_names
            else 0.0,
            "runtime_status_counts": runtime_status_counts,
            "covered_runtime_status_counts": covered_runtime_status_counts,
            "uncovered_by_namespace": dict(sorted(uncovered_by_namespace.items())),
            "out_of_scope_usage_count": len(out_of_scope_usage),
        },
        "interpretation": (
            "This is test-input coverage, not a fidelity score. A covered command "
            "has at least one checked-in behavior-pack case; it may still need "
            "deeper semantic and TMOS 17.5 differential vectors."
        ),
        "packs": sorted(pack_rows, key=lambda pack: pack["name"]),
        "commands": commands,
        "out_of_scope_usage": out_of_scope_usage,
    }


def _runtime_status_map(root: Path) -> tuple[Any, dict[str, str]]:
    """Return the tcl-lsp registry and runtime status for each command."""
    _load_session_class(root)
    try:
        from compiler.registry import REGISTRY
    except ImportError as exc:  # pragma: no cover - depends on external checkout
        raise EmulatorInputError(f"could not load tcl-lsp command registry: {exc}") from exc
    tcl_dir = root / "tooling" / "irule_test" / "tcl"
    handwritten = _proc_names(tcl_dir / "command_mocks.tcl")
    generated = _proc_names(tcl_dir / "_mock_stubs.tcl")
    status_map: dict[str, str] = {}
    for name in _f5_catalog_command_names(REGISTRY):
        status_map[name] = _capability_status(_mock_proc_name(name), handwritten, generated)
    return REGISTRY, status_map


def _is_f5_runtime_command(name: str, spec: Any) -> bool:
    """Avoid warning on ordinary Tcl control commands in a rule."""
    return _catalog_kind(name, spec) == "f5-irule"


def _rule_priority(value: str, context: str) -> int:
    """Validate one TMOS event priority declaration."""
    try:
        priority = int(value, 10)
    except (TypeError, ValueError):
        raise EmulatorInputError(f"{context} priority must be an integer from 0 through 1000") from None
    if not 0 <= priority <= 1000:
        raise EmulatorInputError(f"{context} priority must be an integer from 0 through 1000")
    return priority


def _rule_timing(value: str, context: str) -> str:
    """Normalize the timing spelling accepted by the pinned Tcl loader."""
    normalized = value.lower()
    if normalized in {"on", "enable"}:
        return "on"
    if normalized in {"off", "disable"}:
        return "off"
    raise EmulatorInputError(f"{context} timing must be on or off")


def _prepare_irule_source(
    root: Path, source: str
) -> tuple[str, list[dict[str, Any]]]:
    """Apply top-level ``priority``/``timing`` directives to event headers.

    The pinned tcl-lsp loader already handles explicit ``when EVENT priority N``
    headers, but it intentionally does not interpret the outer-scope forms.
    Segmenting the source with tcl-lsp keeps directives inside braced handler
    bodies from being mistaken for outer-scope declarations. The returned
    source is only a normalized copy; the user's source remains unchanged.
    """
    try:
        _load_session_class(root)
        from compiler.parsing.green_tree import tokenise
        from shared.tokens import TokenType
    except ImportError as exc:  # pragma: no cover - depends on external checkout
        raise EmulatorInputError(f"could not load tcl-lsp source parser: {exc}") from exc

    try:
        lex_tokens, _ = tokenise(source, 0, 0, 0)
        commands: list[tuple[list[str], list[Any]]] = []
        argv: list[Any] = []
        texts: list[str] = []

        def flush() -> None:
            if argv:
                commands.append((list(texts), list(argv)))
            argv.clear()
            texts.clear()

        previous_type = TokenType.EOL
        for token in lex_tokens:
            if token.type is TokenType.COMMENT:
                previous_type = token.type
                continue
            if token.type is TokenType.EOL:
                flush()
                previous_type = token.type
                continue
            if token.type is TokenType.SEP:
                previous_type = token.type
                continue
            # The upstream loader accepts adjacent ``when`` blocks in a
            # single line even though Tcl normally requires a separator. A
            # braced body is an unambiguous boundary for that compatibility
            # form, so split it here before interpreting attributes.
            if (
                token.text == "when"
                and texts
                and texts[0] == "when"
                and argv[-1].type is TokenType.STR
            ):
                flush()
                previous_type = TokenType.SEP
            if previous_type in (TokenType.SEP, TokenType.EOL):
                argv.append(token)
                texts.append(token.text)
            elif texts:
                texts[-1] += token.text
            previous_type = token.type
        flush()
    except Exception as exc:  # pragma: no cover - parser compatibility guard
        raise EmulatorInputError(f"could not parse iRule source controls: {exc}") from exc

    active_priority = 500
    active_timing = "on"
    replacements: list[tuple[int, int, str]] = []
    controls: list[dict[str, Any]] = []

    for texts, argv in commands:
        command_name = texts[0] if texts else ""
        if command_name == "priority":
            if len(texts) != 2:
                raise EmulatorInputError("priority requires exactly one value")
            active_priority = _rule_priority(texts[1], "outer")
            continue
        if command_name == "timing":
            if len(texts) != 2:
                raise EmulatorInputError("timing requires exactly one value")
            active_timing = _rule_timing(texts[1], "outer")
            continue
        if command_name != "when" or len(texts) < 3 or not argv:
            continue
        body_token = argv[-1]
        if body_token.type is not TokenType.STR or len(texts) < 3:
            continue

        event_name = texts[1]
        priority = active_priority
        timing = active_timing
        header = texts[2:-1]
        index = 0
        while index < len(header):
            keyword = header[index]
            if keyword == "priority":
                if index + 1 >= len(header):
                    raise EmulatorInputError(
                        f"when {event_name} priority requires a value"
                    )
                priority = _rule_priority(header[index + 1], f"when {event_name}")
                index += 2
                continue
            if keyword == "timing":
                if index + 1 >= len(header):
                    raise EmulatorInputError(
                        f"when {event_name} timing requires a value"
                    )
                timing = _rule_timing(header[index + 1], f"when {event_name}")
                index += 2
                continue
            raise EmulatorInputError(
                f"when {event_name} has unsupported event attribute {keyword}"
            )

        # Replace only the command header, leaving the body byte-for-byte
        # intact. Offsets are character offsets in the tcl-lsp token model,
        # which matches Python string slicing for the decoded source.
        header_start = argv[0].start.offset
        body_start = body_token.start.offset
        replacements.append(
            (
                header_start,
                body_start,
                f"when {event_name} priority {priority} timing {timing} ",
            )
        )
        controls.append(
            {
                "ordinal": len(controls),
                "event": event_name,
                "priority": priority,
                "timing": timing,
            }
        )

    prepared = source
    for start, end, replacement in reversed(replacements):
        prepared = prepared[:start] + replacement + prepared[end:]
    # BIG-IP exposes these DOSL7 event values as predefined variables.  The
    # Tcl test loader executes handlers as ordinary global procs, where an
    # unqualified variable name would otherwise be local to the handler.
    for variable_name in (
        "DOSL7_ATTACKER_IP",
        "DOSL7_MITIGATION",
        "XML_count",
        "XML_queries",
        "XML_values",
    ):
        prepared = re.sub(
            rf"\$\{{{variable_name}\}}",
            f"${{{'::' + variable_name}}}",
            prepared,
        )
        prepared = re.sub(
            rf"(?<![:A-Za-z0-9_])\${variable_name}(?![A-Za-z0-9_])",
            f"$::{variable_name}",
            prepared,
        )
    return prepared, controls


def _analyze_rule_capabilities(
    root: Path,
    source: str,
    profiles: list[str],
) -> dict[str, Any]:
    """Statically map used commands/events to catalog runtime support."""
    try:
        _load_session_class(root)
        from compiler.irules_flow import _find_when_bodies
        from compiler.parsing.command_segmenter import segment_commands
        from compiler.parsing.token_scanning import scan_command_substitutions
        from compiler.registry.namespace_registry import NAMESPACE_REGISTRY
        from compiler.registry.runtime import body_arg_indices
        from shared.tokens import TokenType

        registry, status_map = _runtime_status_map(root)
        usage: dict[str, dict[str, Any]] = {}
        event_names: set[str] = set()
        visited_scripts: set[tuple[str, str]] = set()

        def visit(script: str, event_name: str) -> None:
            visit_key = (event_name, script)
            if visit_key in visited_scripts:
                return
            visited_scripts.add(visit_key)
            commands = segment_commands(
                script,
                registry_snapshot=registry,
                recovery=False,
            )
            for command in commands:
                name = command.name
                if not name:
                    continue
                entry = usage.setdefault(
                    name,
                    {"name": name, "occurrences": 0, "events": set()},
                )
                entry["occurrences"] += 1
                entry["events"].add(event_name)

                body_indices = body_arg_indices(name, command.args)
                if name == "when" and command.texts:
                    body_indices = [len(command.args) - 1]
                for index in body_indices:
                    text_index = index + 1
                    if 0 <= text_index < len(command.texts):
                        visit(command.texts[text_index], event_name)
                for token in command.all_tokens:
                    if token.type is TokenType.CMD:
                        visit(token.text, event_name)
                    elif token.type is TokenType.STR:
                        for nested in scan_command_substitutions(token.text):
                            visit(nested.text, event_name)

        for event_name, _priority, body, _body_token, _event_token in _find_when_bodies(source):
            event_names.add(event_name)
            visit(body, event_name)

        warnings: list[dict[str, Any]] = []
        command_rows: list[dict[str, Any]] = []
        for name in sorted(usage):
            spec = _f5_catalog_spec(registry, name) or registry.get_any(name)
            status = status_map.get(name)
            if status is None:
                status = "unknown-command" if spec is None else "no-runtime-handler"
            target_status = _target_status(
                name,
                TMOS_17_5_POST_TARGET_COMMANDS,
                TMOS_17_5_UNAVAILABLE_COMMANDS,
            )
            row = {
                "name": name,
                "occurrences": usage[name]["occurrences"],
                "events": sorted(usage[name]["events"]),
                "runtime_status": status,
                "target_status": target_status,
            }
            command_rows.append(row)
            if target_status != "available-in-tmos-17.5":
                if target_status == "introduced-after-tmos-17.5":
                    message = f"{name} was introduced after TMOS 17.5"
                else:
                    message = f"{name} is unavailable in TMOS 17.5"
                warnings.append(
                    {
                        "code": "version-incompatible",
                        "severity": "error",
                        "command": name,
                        "target_status": target_status,
                        "message": message,
                    }
                )
            elif status in {"generated-stub", "no-runtime-handler"} and spec is not None:
                if _is_f5_runtime_command(name, spec):
                    warnings.append(
                        {
                            "code": "runtime-fidelity",
                            "severity": "warning",
                            "command": name,
                            "runtime_status": status,
                            "message": (
                                f"{name} is recognized by the 17.5 catalog but uses a "
                                f"{status.replace('-', ' ')} at runtime"
                            ),
                        }
                    )
            elif status == "unknown-command":
                warnings.append(
                    {
                        "code": "unknown-command",
                        "severity": "warning",
                        "command": name,
                        "message": f"{name} is not present in the pinned 17.5 catalog",
                    }
                )

        attached_profiles = {profile.upper() for profile in profiles}
        for event_name in sorted(event_names):
            props = NAMESPACE_REGISTRY.get_props(event_name)
            event_target_status = _target_status(
                event_name,
                TMOS_17_5_POST_TARGET_EVENTS,
                TMOS_17_5_UNAVAILABLE_EVENTS,
            )
            if event_target_status != "available-in-tmos-17.5":
                if event_target_status == "introduced-after-tmos-17.5":
                    message = f"{event_name} was introduced after TMOS 17.5"
                else:
                    message = f"{event_name} is unavailable in TMOS 17.5"
                warnings.append(
                    {
                        "code": "version-incompatible",
                        "severity": "error",
                        "event": event_name,
                        "target_status": event_target_status,
                        "message": message,
                    }
                )
            required = set(props.implied_profiles) if props is not None else set()
            if required and not required.intersection(attached_profiles):
                warnings.append(
                    {
                        "code": "profile-gated-event",
                        "severity": "warning",
                        "event": event_name,
                        "required_profiles": sorted(required),
                        "message": (
                            f"{event_name} is registered but the attached profiles do not "
                            "include a profile that enables it"
                        ),
                    }
                )
        return {
            "analysis": "static-tcl-lsp",
            "commands": command_rows,
            "events": sorted(event_names),
            "warnings": warnings,
        }
    except Exception as exc:  # pragma: no cover - parser version compatibility guard
        return {
            "analysis": "unavailable",
            "commands": [],
            "events": [],
            "warnings": [
                {
                    "code": "analysis-unavailable",
                    "severity": "warning",
                    "message": f"could not statically analyze rule usage: {exc}",
                }
            ],
        }


def _lsp_diagnostic_to_api_dict(diagnostic: Any) -> dict[str, Any]:
    """Serialize one Tcl-LSP diagnostic without leaking provider objects."""
    severity = getattr(diagnostic, "severity", None)
    severity_name = getattr(severity, "name", None)
    if not isinstance(severity_name, str) or not severity_name:
        severity_name = "error"
    result: dict[str, Any] = {
        "source": "tcl-lsp",
        "code": diagnostic.code if diagnostic.code is not None else "",
        "severity": severity_name.lower(),
        "message": str(diagnostic.message),
        "range": {
            "start": {
                "line": diagnostic.range.start.line,
                "character": diagnostic.range.start.character,
            },
            "end": {
                "line": diagnostic.range.end.line,
                "character": diagnostic.range.end.character,
            },
        },
    }
    return result


def _compatibility_warning_to_api_dict(warning: dict[str, Any]) -> dict[str, Any]:
    """Expose a static TMOS compatibility warning as a source-less diagnostic."""
    result: dict[str, Any] = {
        "source": "testcl",
        "category": "compatibility",
        "code": warning.get("code", "compatibility"),
        "severity": warning.get("severity", "warning"),
        "message": warning.get("message", "TMOS compatibility warning"),
        "range": None,
    }
    for field in (
        "command",
        "event",
        "target_status",
        "runtime_status",
        "required_profiles",
    ):
        if field in warning:
            result[field] = warning[field]
    return result


def run_irule_analysis(
    request: Any,
    *,
    tcl_lsp_root: str | None = None,
    backend: str = "inprocess",
) -> dict[str, Any]:
    """Run bounded Tcl-LSP and TMOS 17.5 compatibility preflight on one rule.

    This operation is intentionally read-only: it parses and analyses source,
    but never creates a Tcl interpreter or executes the rule.  Tcl-LSP ranges
    retain the standard zero-based LSP line/character convention.
    """
    if backend != "inprocess":
        raise EmulatorInputError(
            "the tmos-17.5 analyzer requires the in-process Tcl-LSP backend"
        )
    if not isinstance(request, dict):
        raise EmulatorInputError("iRule analysis request must be a JSON object")
    allowed = {"irule", "profiles", "include_fidelity"}
    unknown = sorted(set(request) - allowed)
    if unknown:
        raise EmulatorInputError(
            f"unsupported iRule analysis field(s): {', '.join(unknown)}"
        )
    source = _require_string(request.get("irule"), "irule")
    if not source.strip():
        raise EmulatorInputError("irule must be a non-empty source string")
    if "\x00" in source:
        raise EmulatorInputError("irule must not contain NUL characters")
    try:
        source_bytes = len(source.encode("utf-8"))
    except UnicodeEncodeError as exc:
        raise EmulatorInputError("irule must contain valid Unicode text") from exc
    if source_bytes > IRULE_ANALYSIS_MAX_SOURCE_BYTES:
        raise EmulatorInputError(
            f"irule exceeds the {IRULE_ANALYSIS_MAX_SOURCE_BYTES}-byte analysis limit"
        )
    source_lines = source.splitlines() or [source]
    if source.count("\n") + 1 > IRULE_ANALYSIS_MAX_LINES:
        raise EmulatorInputError(
            f"irule exceeds the {IRULE_ANALYSIS_MAX_LINES}-line analysis limit"
        )
    try:
        line_sizes = [len(line.encode("utf-8")) for line in source_lines]
    except UnicodeEncodeError as exc:
        raise EmulatorInputError("irule must contain valid Unicode text") from exc
    if any(size > IRULE_ANALYSIS_MAX_LINE_BYTES for size in line_sizes):
        raise EmulatorInputError(
            f"each iRule source line must be at most {IRULE_ANALYSIS_MAX_LINE_BYTES} UTF-8 bytes"
        )

    profiles = request.get("profiles", DEFAULT_PROFILES)
    if not isinstance(profiles, list) or not profiles or len(profiles) > IRULE_ANALYSIS_MAX_PROFILES:
        raise EmulatorInputError(
            f"profiles must be a non-empty array of at most {IRULE_ANALYSIS_MAX_PROFILES} strings"
        )
    if not all(isinstance(profile, str) and profile.strip() for profile in profiles):
        raise EmulatorInputError("profiles must contain non-empty strings")
    try:
        profile_sizes = [len(profile.encode("utf-8")) for profile in profiles]
    except UnicodeEncodeError as exc:
        raise EmulatorInputError("profiles must contain valid Unicode text") from exc
    if any("\x00" in profile or size > 256 for profile, size in zip(profiles, profile_sizes)):
        raise EmulatorInputError(
            "profiles must not contain NUL and must be at most 256 UTF-8 bytes each"
        )
    include_fidelity = request.get("include_fidelity", True)
    if not isinstance(include_fidelity, bool):
        raise EmulatorInputError("include_fidelity must be a boolean")

    root = _find_tcl_lsp_root(tcl_lsp_root)
    try:
        _load_session_class(root)
        from compiler.registry.dialect import dialect_scope
        from server.features.diagnostics import get_basic_diagnostics

        with dialect_scope("f5-irules"):
            diagnostics, _, _ = get_basic_diagnostics(
                source,
                optimiser_enabled=False,
                line_ending="\n",
            )
    except (ImportError, RuntimeError, TypeError, ValueError) as exc:
        raise EmulatorInputError(f"could not analyze iRule source: {exc}") from exc

    diagnostics_truncated = len(diagnostics) > IRULE_ANALYSIS_MAX_DIAGNOSTICS
    api_diagnostics = [
        _lsp_diagnostic_to_api_dict(diagnostic)
        for diagnostic in diagnostics[:IRULE_ANALYSIS_MAX_DIAGNOSTICS]
    ]
    fidelity: dict[str, Any] | None = None
    compatibility_diagnostics: list[dict[str, Any]] = []
    if include_fidelity:
        fidelity = _analyze_rule_capabilities(root, source, list(profiles))
        compatibility_diagnostics = [
            _compatibility_warning_to_api_dict(warning)
            for warning in fidelity.get("warnings", [])
            if isinstance(warning, dict)
        ]

    all_diagnostics = api_diagnostics + compatibility_diagnostics
    errors = sum(item.get("severity") == "error" for item in all_diagnostics)
    warnings = sum(item.get("severity") == "warning" for item in all_diagnostics)
    information = sum(item.get("severity") == "information" for item in all_diagnostics)
    hints = sum(item.get("severity") == "hint" for item in all_diagnostics)
    result: dict[str, Any] = {
        "status": "ok",
        "schema_version": 1,
        "profile": "tmos-17.5",
        "tmos_version": TMOS_VERSION,
        "analysis": "tcl-lsp-basic",
        "source_bytes": source_bytes,
        "valid": errors == 0,
        "diagnostics": all_diagnostics,
        "diagnostic_summary": {
            "total": len(all_diagnostics),
            "errors": errors,
            "warnings": warnings,
            "information": information,
            "hints": hints,
            "truncated": diagnostics_truncated,
        },
    }
    if fidelity is not None:
        result["fidelity"] = fidelity
    return result


def _require_string(value: Any, field: str) -> str:
    if not isinstance(value, str):
        raise EmulatorInputError(f"{field} must be a string")
    return value


def _x509_name_text(name: Any) -> str:
    """Render a cryptography X.509 name in the order used by iRules.

    ``Name.rfc4514_string()`` reverses the RDN sequence.  BIG-IP's examples
    expose the certificate's original sequence, so retain the order supplied
    by the certificate and apply the RFC 2253-style escaping used by the
    existing Tcl fixtures.
    """
    try:
        from cryptography.x509.oid import NameOID
    except ImportError:  # pragma: no cover - dependency is locked in pyproject
        return str(name)

    short_names = {
        NameOID.COMMON_NAME: "CN",
        NameOID.COUNTRY_NAME: "C",
        NameOID.DOMAIN_COMPONENT: "DC",
        NameOID.EMAIL_ADDRESS: "emailAddress",
        NameOID.GIVEN_NAME: "GN",
        NameOID.LOCALITY_NAME: "L",
        NameOID.ORGANIZATION_NAME: "O",
        NameOID.ORGANIZATIONAL_UNIT_NAME: "OU",
        NameOID.POSTAL_CODE: "postalCode",
        NameOID.SERIAL_NUMBER: "serialNumber",
        NameOID.STATE_OR_PROVINCE_NAME: "ST",
        NameOID.STREET_ADDRESS: "street",
        NameOID.SURNAME: "SN",
        NameOID.USER_ID: "UID",
    }

    def escape(value: str) -> str:
        value = value.replace("\\", "\\\\")
        value = value.replace(",", "\\,").replace("+", "\\+")
        value = value.replace('"', '\\"').replace("<", "\\<")
        value = value.replace(">", "\\>").replace(";", "\\;")
        value = value.replace("=", "\\=")
        if value.startswith((" ", "#")):
            value = "\\" + value
        if value.endswith(" "):
            value = value[:-1] + "\\ "
        return value

    rendered: list[str] = []
    for rdn in name.rdns:
        attributes = []
        for attribute in rdn:
            label = short_names.get(attribute.oid, attribute.oid.dotted_string)
            value = attribute.value
            if not isinstance(value, str):
                value = str(value)
            attributes.append(f"{label}={escape(value)}")
        rendered.append("+".join(attributes))
    return ",".join(rendered)


def _x509_date_text(value: Any) -> str:
    """Render a certificate datetime in OpenSSL/F5's conventional form."""
    value = value.replace(tzinfo=None)
    months = ("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")
    return f"{months[value.month - 1]} {value.day:2d} {value:%H:%M:%S} {value:%Y} GMT"


def _x509_extension_text(certificate: Any) -> str:
    """Render the common OpenSSL-style extension summary used by X509::extensions."""
    from cryptography import x509

    values: list[str] = []
    extension_names = {
        "basicConstraints": "X509v3 Basic Constraints",
        "subjectAltName": "X509v3 Subject Alternative Name",
        "keyUsage": "X509v3 Key Usage",
        "extendedKeyUsage": "X509v3 Extended Key Usage",
        "subjectKeyIdentifier": "X509v3 Subject Key Identifier",
        "authorityKeyIdentifier": "X509v3 Authority Key Identifier",
    }
    friendly_eku = {
        "1.3.6.1.5.5.7.3.1": "TLS Web Server Authentication",
        "1.3.6.1.5.5.7.3.2": "TLS Web Client Authentication",
        "1.3.6.1.5.5.7.3.3": "Code Signing",
        "1.3.6.1.5.5.7.3.4": "E-mail Protection",
        "1.3.6.1.5.5.7.3.8": "Time Stamping",
        "1.3.6.1.5.5.7.3.9": "OCSP Signing",
    }
    for extension in certificate.extensions:
        oid_name = getattr(extension.oid, "_name", None)
        name = extension_names.get(oid_name, oid_name or extension.oid.dotted_string)
        value = extension.value
        if isinstance(value, x509.BasicConstraints):
            rendered = f"CA:{'TRUE' if value.ca else 'FALSE'}"
            if value.path_length is not None:
                rendered += f", pathlen:{value.path_length}"
        elif isinstance(value, x509.SubjectAlternativeName):
            rendered = ", ".join(
                (
                    f"DNS:{entry.value}" if isinstance(entry, x509.DNSName)
                    else f"IP Address:{entry.value}" if isinstance(entry, x509.IPAddress)
                    else f"email:{entry.value}" if isinstance(entry, x509.RFC822Name)
                    else f"URI:{entry.value}" if isinstance(entry, x509.UniformResourceIdentifier)
                    else str(entry.value)
                )
                for entry in value
            )
        elif isinstance(value, x509.KeyUsage):
            usages = [
                label for label, present in (
                    ("Digital Signature", value.digital_signature),
                    ("Key Encipherment", value.key_encipherment),
                    ("Key Agreement", value.key_agreement),
                    ("Certificate Sign", value.key_cert_sign),
                    ("CRL Sign", value.crl_sign),
                    ("Content Commitment", value.content_commitment),
                    ("Data Encipherment", value.data_encipherment),
                ) if present
            ]
            rendered = ", ".join(usages)
        elif isinstance(value, x509.ExtendedKeyUsage):
            rendered = ", ".join(
                friendly_eku.get(usage.dotted_string, usage.dotted_string)
                for usage in value
            )
        elif isinstance(value, x509.SubjectKeyIdentifier):
            rendered = ":".join(f"{byte:02X}" for byte in value.digest)
        elif isinstance(value, x509.AuthorityKeyIdentifier):
            rendered = (
                ":".join(f"{byte:02X}" for byte in value.key_identifier)
                if value.key_identifier is not None else ""
            )
        else:
            rendered = str(value)
        values.extend([f"    {name}:", f"        {rendered}"])
    if not values:
        return "(no extensions)"
    return "X509v3 extensions:\n" + "\n".join(values)


def _normalise_tls_certificate_bytes(packet: dict[str, Any], packet_index: int) -> None:
    """Populate TLS certificate fields from a valid PEM or hexadecimal DER value.

    Structured tests historically supplied individual certificate fields,
    including deliberately invalid PEM.  Those fixtures remain authoritative
    when no valid certificate bytes are available.  When valid bytes are
    supplied, the certificate is authoritative and derived fields replace any
    conflicting metadata so rules exercise the same object consistently.
    """
    if "cert_pem" not in packet and "cert_der" not in packet:
        return

    pem = packet.get("cert_pem")
    if isinstance(pem, str):
        try:
            pem_size = len(pem.encode("utf-8"))
        except UnicodeEncodeError as exc:
            raise EmulatorInputError(
                f"packet {packet_index} TLS cert_pem must be valid UTF-8"
            ) from exc
        if pem_size > TLS_CERT_MAX_BYTES:
            raise EmulatorInputError(
                f"packet {packet_index} TLS cert_pem exceeds "
                f"{TLS_CERT_MAX_BYTES // (1024 * 1024)} MiB"
            )
    raw_der = packet.get("cert_der")
    if isinstance(raw_der, str) and len(raw_der) > TLS_CERT_MAX_BYTES * 2:
        raise EmulatorInputError(
            f"packet {packet_index} TLS cert_der exceeds "
            f"{TLS_CERT_MAX_BYTES * 2} hexadecimal characters"
        )

    from cryptography import x509
    from cryptography.hazmat.primitives import serialization
    from cryptography.hazmat.primitives.asymmetric import dsa, ec, ed25519, ed448, rsa
    from cryptography.exceptions import UnsupportedAlgorithm

    certificate = None
    der: bytes | None = None
    if isinstance(pem, str) and pem.strip():
        try:
            certificate = x509.load_pem_x509_certificate(pem.encode("ascii"))
            der = certificate.public_bytes(serialization.Encoding.DER)
        except (UnicodeEncodeError, ValueError, TypeError):
            certificate = None
    if certificate is None:
        if isinstance(raw_der, str) and re.fullmatch(r"[0-9A-Fa-f]+", raw_der.strip()):
            encoded_der = raw_der.strip()
            if len(encoded_der) % 2 == 0:
                try:
                    der = bytes.fromhex(encoded_der)
                    certificate = x509.load_der_x509_certificate(der)
                except (ValueError, TypeError):
                    certificate = None
                    der = None
    if certificate is None or der is None:
        return

    public_key = certificate.public_key()
    try:
        signature_hash_name = certificate.signature_hash_algorithm.name
    except (UnsupportedAlgorithm, ValueError):
        signature_hash_name = certificate.signature_algorithm_oid.dotted_string
    if isinstance(public_key, rsa.RSAPublicKey):
        key_type = "RSA"
        key_bits = public_key.key_size
        key_curve = ""
        signature_name = signature_hash_name + "WithRSAEncryption"
    elif isinstance(public_key, dsa.DSAPublicKey):
        key_type = "DSA"
        key_bits = public_key.key_size
        key_curve = ""
        signature_name = signature_hash_name + "WithDSA"
    elif isinstance(public_key, ec.EllipticCurvePublicKey):
        key_type = "EC"
        key_bits = public_key.key_size
        key_curve = public_key.curve.name
        signature_name = "ecdsa-with-" + signature_hash_name.upper()
    elif isinstance(public_key, (ed25519.Ed25519PublicKey, ed448.Ed448PublicKey)):
        key_type = "ED25519" if isinstance(public_key, ed25519.Ed25519PublicKey) else "ED448"
        key_bits = public_key.key_size
        key_curve = ""
        signature_name = certificate.signature_algorithm_oid.dotted_string
    else:
        key_type = "unknown"
        key_bits = 0
        key_curve = ""
        signature_name = certificate.signature_algorithm_oid.dotted_string

    try:
        not_valid_before = certificate.not_valid_before_utc
        not_valid_after = certificate.not_valid_after_utc
    except AttributeError:  # pragma: no cover - compatibility with older cryptography
        not_valid_before = certificate.not_valid_before
        not_valid_after = certificate.not_valid_after
    public_key_pem = public_key.public_bytes(
        serialization.Encoding.PEM,
        serialization.PublicFormat.SubjectPublicKeyInfo,
    ).decode("ascii")
    packet.update({
        "cert_count": packet.get("cert_count", 1),
        "cert_subject": _x509_name_text(certificate.subject),
        "cert_issuer": _x509_name_text(certificate.issuer),
        "cert_serial": format(certificate.serial_number, "X"),
        "cert_hash": ":".join(
            f"{byte:02X}"
            for byte in hashlib.md5(der, usedforsecurity=False).digest()
        ),
        "cert_extensions": _x509_extension_text(certificate),
        "cert_not_valid_before": _x509_date_text(not_valid_before),
        "cert_not_valid_after": _x509_date_text(not_valid_after),
        "cert_signature_algorithm": signature_name,
        "cert_public_key": public_key_pem,
        "cert_public_key_type": key_type,
        "cert_public_key_bits": key_bits,
        "cert_public_key_curve": key_curve,
        "cert_version": certificate.version.value + 1,
        "cert_pem": certificate.public_bytes(serialization.Encoding.PEM).decode("ascii"),
    })


def _tcl_quote(value: str) -> str:
    """Quote a string for one Tcl word without enabling substitutions."""
    if "\x00" in value:
        raise EmulatorInputError("Tcl strings cannot contain NUL bytes")
    escaped = (
        value.replace("\\", "\\\\")
        .replace('"', '\\"')
        .replace("$", "\\$")
        .replace("[", "\\[")
        .replace("]", "\\]")
        .replace("\n", "\\n")
        .replace("\r", "\\r")
        .replace("\t", "\\t")
    )
    escaped = "".join(
        f"\\u{ord(character):04x}"
        if ord(character) < 0x20 or ord(character) == 0x7F
        else character
        for character in escaped
    )
    return f'"{escaped}"'


def _tcl_list(values: list[str]) -> str:
    return "{" + " ".join(_tcl_quote(value) for value in values) + "}"


def _tcl_list_value(values: list[str]) -> str:
    """Encode a Tcl list as a variable value rather than command syntax."""
    return " ".join(_tcl_quote(value) for value in values)


def _tcl_dict_value(values: dict[str, str]) -> str:
    """Encode a flat Tcl dictionary as a variable value."""
    flattened = [item for key, value in values.items() for item in (key, value)]
    return _tcl_list_value(flattened)


def _configure_asm(session: Any, asm: dict[str, Any]) -> None:
    """Install the deterministic ASM/WAF policy inputs in the Tcl session."""
    scalar_values = (
        "1" if asm["enabled"] else "0",
        asm["policy"],
        asm["client_ip"],
        asm["fingerprint"],
        asm["username"],
        asm["login_status"],
        asm["microservice"],
        asm["status"],
        asm["severity"],
        asm["support_id"],
        asm["captcha_status"],
        str(asm["captcha_age"]),
        asm["payload"],
    )
    session.eval_tcl(
        "::itest::semantic::asm_configure "
        + " ".join(_tcl_quote(value) for value in scalar_values)
    )

    records: list[str] = []
    for violation in asm["violations"]:
        details_flattened = [
            item
            for key, value in violation["details"].items()
            for item in (key, value)
        ]
        records.append(
            " ".join(
                [
                    _tcl_quote(violation["name"]),
                    _tcl_quote(violation["attack_type"]),
                    _tcl_quote(violation["rating"]),
                    _tcl_list(details_flattened),
                ]
            )
        )
    command = "::itest::semantic::asm_set_violations"
    if records:
        command += " " + " ".join(_tcl_quote(record) for record in records)
    session.eval_tcl(command)
    response_records: list[str] = []
    for violation in asm["response_violations"]:
        details_flattened = [
            item
            for key, value in violation["details"].items()
            for item in (key, value)
        ]
        response_records.append(
            " ".join(
                [
                    _tcl_quote(violation["name"]),
                    _tcl_quote(violation["attack_type"]),
                    _tcl_quote(violation["rating"]),
                    _tcl_list(details_flattened),
                ]
            )
        )
    response_command = "::itest::semantic::asm_set_response_violations"
    if response_records:
        response_command += " " + " ".join(
            _tcl_quote(record) for record in response_records
        )
    session.eval_tcl(response_command)
    response_login = asm["response_login"]
    session.eval_tcl(
        "::itest::semantic::asm_set_response_login "
        + " ".join(
            _tcl_quote(value)
            for value in (
                "1" if response_login["enabled"] else "0",
                response_login["status"],
                response_login["username"],
            )
        )
    )
    for field in ASM_SIGNATURE_FIELDS:
        session.eval_tcl(
            "::itest::semantic::asm_set_signatures "
            f"{_tcl_quote(field)} "
            f"{_tcl_list(asm['signatures'][field])}"
        )
    for field in ASM_CAMPAIGN_FIELDS:
        session.eval_tcl(
            "::itest::semantic::asm_set_campaigns "
            f"{_tcl_quote(field)} "
            f"{_tcl_list(asm['threat_campaigns'][field])}"
        )
    session.eval_tcl("::itest::semantic::asm_prepare_request 0 \"\"")


